'use strict';
const $ = id => document.getElementById(id);
function escapeHTML(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
let toastTimer;
function premiumToast(message){let el=$('premium-toast');if(!el){el=document.createElement('div');el.id='premium-toast';el.className='premium-toast';el.setAttribute('role','status');document.body.append(el);}el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4200);}
function storageGet(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function storageSet(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
const CHECKPOINT='pome-premium-checkpoint-v1', RECORDS='pome-premium-records-v1';
function saveCheckpoint(){if(state.currentScreen!=='game')return false;const data={};['studentName','studentClass','selectedAvatar','controlMode','stage','questionIndex','stage3MissionIndex','score','streak','maxStreak','stageScores','answers','missionCompleted','stage3Matches','selectedStage3CardId','reactorCooled','reactorNeutralized','reactorBoostClicks'].forEach(k=>data[k]=state[k]);data.savedAt=Date.now();return storageSet(CHECKPOINT,data);}
function stopCamera(){visionGeneration++;state.cameraReady=false;state.currentGestureKey=null;if(webcamStream){webcamStream.getTracks().forEach(t=>t.stop());webcamStream=null;}for(const id of ['webcam-video','debug-webcam-video']){const v=$(id);if(v)v.srcObject=null;}$('fps-badge').textContent='-- FPS';updateGestureHUD('Kamera dihentikan',0);}
function detectVisionSafely(model,video,now){try{return model.detectForVideo(video,now);}catch(err){console.error('POME vision inference:',err);stopCamera();premiumToast('Pengesanan AI terhenti. Cuba kamera semula atau gunakan klik.');return {landmarks:[],faceLandmarks:[]};}}
function visionSuspended(){return state.controlMode!=='vision'||document.hidden||!!document.querySelector('div[id^="modal-"]:not(.hidden)')||state.currentScreen!=='game';}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<42;i++){const e=document.createElement('i');e.className='confetti-piece';e.style.left=Math.random()*100+'vw';e.style.background=['#c7f779','#5fd6bb','#f2d58c'][i%3];e.style.setProperty('--drift',(Math.random()-.5)*260+'px');e.style.animationDelay=Math.random()*.5+'s';document.body.append(e);setTimeout(()=>e.remove(),3000);}}
// Mission toolbar keeps the primary controls visible during play.
const toolbar=document.createElement('div');toolbar.id='game-toolbar';toolbar.innerHTML='<span id="mission-position" class="toolbar-label">MISI 01 / 03</span><button class="tool-button" id="btn-save-exit">Simpan & keluar</button><button class="tool-button" id="btn-change-control">✋ Aktifkan gesture AI</button><button class="tool-button" id="btn-fullscreen">⛶ Skrin penuh</button><div class="mission-progress" role="progressbar" aria-label="Kemajuan keseluruhan" aria-valuemin="0" aria-valuemax="12"><div id="mission-progress-fill"></div></div>';
$('screen-game').prepend(toolbar);
const manualOverlay=document.createElement('div');manualOverlay.id='manual-camera-cover';manualOverlay.className='camera-manual';manualOverlay.innerHTML='<span style="font-size:32px;color:#c7f779">↖</span><b>Anda di pusat kawalan.</b><p>Pilih kad atau tekan A, B, C, D.<br>Tekan Enter untuk soalan seterusnya.</p><button type="button" id="btn-cover-camera">Cuba gesture AI →</button>';
$('webcam-video').parentElement.append(manualOverlay);
const help=document.createElement('p');help.className='game-help';help.textContent='A / B / C / D · Pilih jawapan     Enter · Seterusnya     Esc · Tutup panel';$('quiz-mode-container').append(help);
const footer=document.createElement('div');footer.className='premium-footer';footer.innerHTML='<span>POME QUESTURE <b style="color:#aac69a">/</b> MAKMAL MISI LESTARI</span><span>SBV60104 · CLO3 · Belajar melalui keputusan</span>';
document.querySelector('main').append(footer);
function updatePremiumUI(){
 const answered=Object.keys(state.answers).length, missions=Object.keys(state.missionCompleted).length;
 $('mission-position').textContent=`MISI 0${state.stage} / 03 · ${answered+missions} DARIPADA 12 AKTIVITI SELESAI`;
 $('mission-progress-fill').style.width=(answered+missions)/12*100+'%';toolbar.querySelector('[role=progressbar]').setAttribute('aria-valuenow',answered+missions);
 $('btn-change-control').textContent=state.controlMode==='vision'?'↖ Tukar ke klik / hentikan kamera':'✋ Aktifkan gesture AI';
 manualOverlay.style.display=state.controlMode==='manual'?'flex':'none';
 for(let i=1;i<=3;i++){const p=$('hud-stage-pill-'+i);p.removeAttribute('onclick');p.setAttribute('aria-current',i===state.stage?'true':'false');}
 const hint=$('question-stage-hint');if(state.controlMode==='manual'&&hint)hint.textContent='↖ Klik jawapan atau tekan A, B, C, D. Enter untuk meneruskan.';
 if(state.controlMode==='manual')document.querySelectorAll('#options-grid .option-card>div:first-child>span:last-child').forEach((el,i)=>el.textContent=['A','B','C','D'][i]+' · Papan kekunci');
 [1,2,3,4].forEach((n)=>{const b=$('badge-item-'+n);const unlocked=[state.stageScores.s1>=3,state.stageScores.s2>=3,state.stageScores.s3>=1,state.maxStreak>=3][n-1];b.classList.toggle('badge-unlocked',unlocked);b.classList.toggle('opacity-45',!unlocked);b.style.opacity=unlocked?'1':'.45';});
}
const baseRender=renderCurrentQuestion;
renderCurrentQuestion=function(){
 baseRender();updatePremiumUI();
 const old=state.answers[`${state.stage}-${state.questionIndex}`];
 if(old&&state.stage<3){state.questionLocked=true;showStoredAnswer(old);}
 saveCheckpoint();
};
function markOptions(selected,correct){document.querySelectorAll('#options-grid .option-card').forEach((el,i)=>{el.disabled=true;el.classList.toggle('answer-correct',i===correct);el.classList.toggle('answer-wrong',i===selected&&i!==correct);el.setAttribute('aria-label',`${['A','B','C','D'][i]}: ${el.querySelector('p').textContent.trim()}${i===correct?' — Jawapan betul':i===selected?' — Pilihan anda':''}`);});}
function showStoredAnswer(answer){const q=(state.stage===1?QUESTIONS_STAGE_1:QUESTIONS_STAGE_2)[state.questionIndex];markOptions(answer.selected,q.correct);$('feedback-banner').classList.remove('hidden');$('feedback-title').textContent=answer.correct?`JAWAPAN TEPAT! (+${state.questionWeight || 5} MARKAH)`:'KURANG TEPAT — MARI BELAJAR';$('feedback-explanation').textContent=q.explanation;$('feedback-icon').textContent=answer.correct?'✓':'↗';$('btn-use-hint').disabled=true;}
const baseSubmit=submitQuizAnswer;
submitQuizAnswer=function(index){
 if(state.currentScreen!=='game'||state.stage===3||state.questionLocked)return;
 const el=document.querySelector(`[data-opt-index="${index}"]`);if(!el||el.disabled)return;
 baseSubmit(index);const q=(state.stage===1?QUESTIONS_STAGE_1:QUESTIONS_STAGE_2)[state.questionIndex];markOptions(index,q.correct);$('btn-use-hint').disabled=true;updatePremiumUI();saveCheckpoint();
 if(index===q.correct&&state.streak>=3)premiumToast(`Hebat! ${state.streak} jawapan tepat berturut-turut.`);
};
// Stage jumping in the source allowed the same answer to score repeatedly.
window.jumpToStage=function(){premiumToast('Lengkapkan peringkat semasa untuk membuka misi berikutnya.');};
const baseBoard=updateStage3BoardUI;
updateStage3BoardUI=function(){baseBoard();
 document.querySelectorAll('.s3-card-item:not(:disabled)').forEach(card=>{card.draggable=true;card.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',card.dataset.cardId);e.dataTransfer.effectAllowed='move';});});
 document.querySelectorAll('.s3-zone-item').forEach(zone=>{const used=!!state.stage3Matches[zone.dataset.zoneId];zone.disabled=used;zone.addEventListener('dragover',e=>{if(!used){e.preventDefault();zone.classList.add('drag-over');}});zone.addEventListener('dragleave',()=>zone.classList.remove('drag-over'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('drag-over');if(used)return;const id=e.dataTransfer.getData('text/plain');const m=STAGE_3_MISSIONS[state.stage3MissionIndex];if(!m.cards.some(c=>c.id===id)||Object.values(state.stage3Matches).includes(id))return;state.selectedStage3CardId=id;handleStage3ZoneAttempt(zone.dataset.zoneId);});});
 updatePremiumUI();saveCheckpoint();
};
const baseMatch=handleStage3ZoneAttempt;
handleStage3ZoneAttempt=function(zone){if(!state.selectedStage3CardId){premiumToast('Pilih kad teknologi dahulu, kemudian pilih stesen.');return;}const count=Object.keys(state.stage3Matches).length;baseMatch(zone);if(Object.keys(state.stage3Matches).length===count)premiumToast('Belum tepat. Semak fungsi teknologi dan cuba stesen yang lain.');updatePremiumUI();saveCheckpoint();};
const baseRenderMission=renderStage3Mission;
renderStage3Mission=function(){baseRenderMission();updatePremiumUI();saveCheckpoint();};
// Prevent a stale completion timer from advancing a different play session.
let missionSession=0;
$('btn-start-game').addEventListener('click',()=>{
 missionSession++;state.controlMode=document.querySelector('[name=play-mode]:checked').value;
 stopCamera();for(const el of document.querySelectorAll('div[id^="modal-"]'))el.classList.add('hidden');
},true);
$('btn-start-game').addEventListener('click',()=>{updatePremiumUI();$('hud-streak-badge').classList.add('hidden');$('hud-streak-count').textContent='';setMascotMood('happy','Misi bermula! Analisis setiap pilihan dan bantu saya pulihkan sungai.');$('selfie-btn-text').textContent='Tangkap Foto Kamera AI ke Sijil';document.querySelectorAll('.confetti-piece').forEach(el=>el.remove());if($('premium-toast'))$('premium-toast').hidden=true;saveCheckpoint();window.scrollTo({top:0,behavior:'smooth'});});
const baseShowScreen=showScreen;
showScreen=function(screen){baseShowScreen(screen);if(screen!=='game'){stopCamera();}if(screen==='welcome')refreshResume();};
function refreshResume(){const saved=storageGet(CHECKPOINT,null);$('btn-resume').hidden=!saved;}
$('btn-resume').addEventListener('click',()=>{
 const saved=storageGet(CHECKPOINT,null);if(!saved)return;
 if(![1,2,3].includes(saved.stage)||!saved.answers||!saved.missionCompleted||!Number.isFinite(saved.score)){premiumToast('Rekod ini tidak dapat dibaca. Mulakan misi baharu.');return;}
 stopCamera();const mode= document.querySelector('[name=play-mode]:checked').value;
 Object.assign(state,saved,{controlMode:mode,cameraReady:false,debugModeActive:false,faceAutoCalibrated:false,sessionSaved:false});
 // Rebuild totals from the completed activities, so a checkpoint cannot double-award points.
 state.stageScores={s1:0,s2:0,s3:Object.values(state.missionCompleted).filter(Boolean).length};for(const [k,v] of Object.entries(state.answers)){if(v.correct){if(k.startsWith('1-'))state.stageScores.s1++;else if(k.startsWith('2-'))state.stageScores.s2++;}}
 state.score=(state.stageScores.s1+state.stageScores.s2)*(state.questionWeight||5)+state.stageScores.s3*20;
 $('input-student-name').value=state.studentName;$('input-student-class').value=state.studentClass;$('hud-student-name').textContent=state.studentName;$('hud-student-class').textContent=state.studentClass;window.selectStudentAvatar(state.selectedAvatar);
 const matches={...state.stage3Matches};
 showScreen('game');renderCurrentQuestion();
 if(state.stage===3){if(state.missionCompleted[state.stage3MissionIndex]){if(state.stage3MissionIndex===0){state.stage3MissionIndex=1;renderStage3Mission();}else{finishMissionAndShowCertificate();return;}}else{state.stage3Matches=matches;updateStage3BoardUI();}}
 if(mode==='vision')startCameraAndAI();premiumToast('Misi disambung. Selamat kembali, jurutera!');
});
$('btn-save-exit').addEventListener('click',()=>{if(!saveCheckpoint()){premiumToast('Pelayar menyekat simpanan. Kekal dalam misi ini untuk meneruskan.');return;}showScreen('welcome');premiumToast('Kemajuan disimpan pada pelayar ini.');window.scrollTo({top:0,behavior:'smooth'});});
async function toggleControl(){if(state.controlMode==='vision'){state.controlMode='manual';stopCamera();}else{state.controlMode='vision';state.awaitNeutral=true;state.faceAutoCalibrated=false;startCameraAndAI();}updatePremiumUI();saveCheckpoint();}
$('btn-change-control').addEventListener('click',toggleControl);$('btn-cover-camera').addEventListener('click',toggleControl);
$('btn-fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{premiumToast('Skrin penuh tidak tersedia dalam paparan ini.');}});
// Turn hint elimination into an actual disabled state, including keyboard/vision input.
$('btn-use-hint').addEventListener('click',()=>{if(!state.hintUsedForQuestion)return;document.querySelectorAll('#options-grid .pointer-events-none').forEach(el=>el.disabled=true);$('btn-use-hint').disabled=true;premiumToast('Dua pilihan disingkirkan. Baca dua jawapan yang tinggal.');});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'){const modal=[...document.querySelectorAll('div[id^="modal-"]:not(.hidden)')].pop();if(modal){modal.classList.add('hidden');if(modal.id==='modal-camera-debug'){state.debugModeActive=false;if(state.currentScreen!=='game')stopCamera();}}return;}
 if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable||e.altKey||e.ctrlKey||e.metaKey)return;
 if(state.currentScreen!=='game'||document.querySelector('div[id^="modal-"]:not(.hidden)'))return;
 const idx='abcd'.indexOf(e.key.toLowerCase());if(e.key.length===1&&idx>=0&&state.stage<3){e.preventDefault();submitQuizAnswer(idx);}else if(e.key==='Enter'&&state.questionLocked&&state.stage<3&&!/BUTTON|SUMMARY/.test(e.target.tagName)){e.preventDefault();advanceToNextQuestion();}
});
// Local leaderboard: text is escaped and records survive a reload on this browser.
memoryLeaderboard=storageGet(RECORDS,[]);if(!Array.isArray(memoryLeaderboard))memoryLeaderboard=[];
memoryLeaderboard=memoryLeaderboard.filter(x=>x&&typeof x.name==='string'&&Number.isFinite(x.score)).slice(0,8);
const baseSaveScore=saveScoreToLeaderboard;
saveScoreToLeaderboard=function(){if(state.sessionSaved)return;baseSaveScore();state.sessionSaved=true;storageSet(RECORDS,memoryLeaderboard);};
window.clearLeaderboard=function(){memoryLeaderboard=[];storageSet(RECORDS,[]);renderLeaderboardTable();premiumToast('Rekod pada pelayar ini telah dikosongkan.');};
// A useful debrief accompanies the certificate rather than only a final score.
const review=document.createElement('details');review.className='learning-notes';review.style.marginTop='24px';review.innerHTML='<summary><span>↗</span><div><b>Semakan keputusan anda</b><small>Lihat jawapan, penerangan dan konsep yang perlu diulang kaji</small></div><span>BUKA SEMAKAN ↓</span></summary><div class="review-list notes-content" id="answer-review"></div>';$('screen-certificate').append(review);
function buildReview(){let html='';[QUESTIONS_STAGE_1,QUESTIONS_STAGE_2].forEach((list,s)=>list.forEach((q,i)=>{const a=state.answers[`${s+1}-${i}`];html+=`<article class="review-item ${a?.correct?'':'wrong'}"><small>${a?.correct?'✓ TEPAT':'↗ ULANG KAJI'} · PERINGKAT ${s+1} / SOALAN ${i+1}${a?.hinted?' · BANTUAN DIGUNAKAN':''}</small><h4>${escapeHTML(q.question)}</h4><p>Pilihan anda: ${a?escapeHTML(q.options[a.selected]):'Belum dijawab'}<br><b style="color:#d9edcc">Jawapan betul: ${escapeHTML(q.options[q.correct])}</b></p><p>${escapeHTML(q.explanation)}</p></article>`;}));$('answer-review').innerHTML=html;}
// Match the certificate to the laboratory identity and fit long student names.
drawCertificateCanvas=function(){
 const c=$('certificate-canvas');c.width=1200;c.height=840;const ctx=c.getContext('2d');
 ctx.fillStyle='#f1f1df';ctx.fillRect(0,0,1200,840);ctx.fillStyle='#143b30';ctx.fillRect(0,0,1200,17);ctx.fillRect(0,803,1200,37);
 ctx.strokeStyle='#adc0a0';ctx.lineWidth=1;ctx.strokeRect(34,34,1132,752);ctx.strokeRect(42,42,1116,736);
 ctx.save();ctx.globalAlpha=.2;ctx.strokeStyle='#8fae76';for(let i=0;i<10;i++){ctx.beginPath();ctx.arc(1160,90,65+i*22,0,Math.PI*2);ctx.stroke();}ctx.restore();
 ctx.fillStyle='#143b30';ctx.font='800 18px "Plus Jakarta Sans",sans-serif';ctx.textAlign='left';ctx.fillText('POME QUESTURE',78,98);ctx.fillStyle='#66806a';ctx.font='11px "Plus Jakarta Sans",sans-serif';ctx.fillText('MAKMAL MISI LESTARI / SBV60104',78,120);
 ctx.textAlign='center';ctx.fillStyle='#55714b';ctx.font='700 13px "Plus Jakarta Sans",sans-serif';ctx.fillText('PENGIKTIRAFAN PENYERTAAN & PENCAPAIAN',600,192);
 ctx.fillStyle='#173b30';ctx.font='800 49px "Plus Jakarta Sans",sans-serif';ctx.fillText('Jurutera Muda Lestari',600,260);
 ctx.fillStyle='#6d7d69';ctx.font='16px "Plus Jakarta Sans",sans-serif';ctx.fillText('Sijil ini diberikan kepada',600,307);
 ctx.fillStyle='#173b30';let size=40;const name=(state.studentName||'JURUTERA MUDA').toUpperCase();do{ctx.font=`800 ${size}px "Plus Jakarta Sans",sans-serif`;if(ctx.measureText(name).width<=990)break;size--;}while(size>18);ctx.fillText(name,600,373,1000);
 ctx.fillStyle='#687a64';ctx.font='15px "Plus Jakarta Sans",sans-serif';ctx.fillText(state.studentClass,600,407,950);
 ctx.strokeStyle='#b1c49f';ctx.beginPath();ctx.moveTo(210,439);ctx.lineTo(990,439);ctx.stroke();
 ctx.fillStyle='#52684d';ctx.font='16px "Plus Jakarta Sans",sans-serif';ctx.fillText('Telah menyelesaikan misi analisis pencemaran, pemulihan sumber',600,480);ctx.fillText('dan reka bentuk aliran rawatan POME dalam makmal maya.',600,505);
 const vals=[`${state.score} / 140`,`${state.stageScores.s1} / ${QUESTIONS_STAGE_1.length}`,`${state.stageScores.s2} / ${QUESTIONS_STAGE_2.length}`,`${state.stageScores.s3} / 2`],labels=['JUMLAH MARKAH','KENALI ANCAMAN','PULIHKAN SUMBER','BINA LOJI'];
 for(let i=0;i<4;i++){const x=118+i*245;ctx.fillStyle=i===0?'#163d30':'#e2e9d1';ctx.fillRect(x,542,230,88);ctx.fillStyle=i===0?'#d4f896':'#214832';ctx.font='800 25px "Plus Jakarta Sans",sans-serif';ctx.fillText(vals[i],x+115,578);ctx.fillStyle=i===0?'#bbd39d':'#728365';ctx.font='700 9px "Plus Jakarta Sans",sans-serif';ctx.fillText(labels[i],x+115,607);}
 const pledges=['Mengutamakan rawatan bersepadu dan pemulihan sumber.','Memulihkan tenaga biogas dan nutrien daripada efluen.','Melindungi ekosistem sungai melalui rawatan POME.'];ctx.fillStyle='#55714b';ctx.font='italic 14px "Plus Jakarta Sans",sans-serif';ctx.fillText(pledges[state.certPledgeIndex]||pledges[0],600,667);
 ctx.textAlign='left';ctx.font='700 13px "Plus Jakarta Sans",sans-serif';ctx.fillStyle='#244b35';ctx.fillText('TEKNOLOGI ALAM SEKITAR · CLO3',78,725);ctx.font='12px "Plus Jakarta Sans",sans-serif';ctx.fillStyle='#7c8d70';ctx.fillText('Aktiviti pembelajaran interaktif',78,747);
 ctx.textAlign='right';ctx.fillStyle='#244b35';ctx.font='700 13px "Plus Jakarta Sans",sans-serif';ctx.fillText(new Date().toLocaleDateString('ms-MY',{day:'numeric',month:'long',year:'numeric'}),1122,725);ctx.font='12px "Plus Jakarta Sans",sans-serif';ctx.fillStyle='#7c8d70';ctx.fillText((AVATAR_PROFILES[state.selectedAvatar]||AVATAR_PROFILES.biogas).title,1122,747);
 if(state.selfieDataUrl){const image=new Image();image.onload=()=>{ctx.save();ctx.beginPath();ctx.arc(1060,112,44,0,Math.PI*2);ctx.clip();ctx.drawImage(image,1016,68,88,88);ctx.restore();};image.src=state.selfieDataUrl;}
};
const baseFinish=finishMissionAndShowCertificate;
finishMissionAndShowCertificate=function(){baseFinish();stopCamera();buildReview();try{localStorage.removeItem(CHECKPOINT);}catch{}refreshResume();celebrate();window.scrollTo({top:0,behavior:'smooth'});};
const baseSelfie=window.captureWebcamToCertificate;
window.captureWebcamToCertificate=async function(){if(!state.cameraReady){premiumToast('Benarkan kamera untuk mengambil foto sijil.');await startCameraAndAI();}baseSelfie();stopCamera();};
// Accessible modal panels: focus stays inside and returns to the opening control.
const modalOpeners=new Map();
document.querySelectorAll('div[id^="modal-"]').forEach(modal=>{
 modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');const title=modal.querySelector('h2,h3');if(title){if(!title.id)title.id=modal.id+'-heading';modal.setAttribute('aria-labelledby',title.id);}modal.firstElementChild?.classList.add('modal-panel');
 let visible=false;new MutationObserver(()=>{const now=!modal.classList.contains('hidden');if(now===visible)return;visible=now;if(now){modalOpeners.set(modal,document.activeElement);state.currentGestureKey=null;modal.querySelector('button,[tabindex]')?.focus();}else{modalOpeners.get(modal)?.focus();state.currentGestureKey=null;state.awaitNeutral=true;}document.body.classList.toggle('modal-open',!!document.querySelector('div[id^="modal-"]:not(.hidden)'));}).observe(modal,{attributes:true,attributeFilter:['class']});
 modal.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const els=[...modal.querySelectorAll('button,input,select,summary,[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length);if(!els.length)return;if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus();}});
});
$('btn-close-debug').addEventListener('click',()=>{if(state.currentScreen!=='game')stopCamera();});
document.querySelectorAll('.scene-station').forEach(station=>{const explore=()=>{const key=station.dataset.sample;window.setMicroscopeSample(key);const text={raw:'Pra-rawatan · Sejukkan efluen dan asingkan minyak.',anaerobic:'Bioreaktor · Pulihkan biogas melalui pencernaan anaerobik.',ro:'Pemulihan · Teroka penapisan dan kitar semula air.'};$('scene-caption-text').textContent=text[key];$('learning-notes').open=true;premiumToast(text[key]);};station.addEventListener('click',explore);station.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();explore();}});});
// Clearly label the original animated microscope and calculator as learning models.
const micro=$('microscope-svg-view');micro.setAttribute('aria-label','Ilustrasi konseptual sampel; bukan imej mikroskop sebenar');
const microscopeHeading=[...document.querySelectorAll('h4')].find(el=>el.textContent.includes('LENSA MIKROSKOP'));if(microscopeHeading)microscopeHeading.textContent='LENSA SAMPEL INTERAKTIF · ILUSTRASI KONSEP';
const calcNote=document.createElement('p');calcNote.className='model-note';calcNote.textContent='Andaian model: 20 jam operasi/hari; 0.65 m³ POME/t FFB; 28 m³ biogas/m³ POME; 2 kWh/m³ biogas; pemulihan air 70%. Anggaran ilustrasi, bukan jaminan hasil.';$('ffb-slider').parentElement.append(calcNote);
document.querySelectorAll('button:not([title])').forEach(el=>{if(!el.textContent.trim())el.setAttribute('aria-label',el.id==='btn-close-simulator'?'Tutup simulasi':el.id==='btn-toggle-sound'?'Togol kesan bunyi':el.id.includes('close')?'Tutup panel':'Kawalan permainan');});
document.addEventListener('visibilitychange',()=>{if(document.hidden){state.currentGestureKey=null;saveCheckpoint();}});
window.addEventListener('beforeunload',()=>{saveCheckpoint();stopCamera();});
refreshResume();renderLeaderboardTable();updatePremiumUI();

// Device-local capability checks: no camera permission is requested by this panel.
function cameraEnvironment(){
 return {protocol:location.protocol,secure:window.isSecureContext===true,api:typeof navigator.mediaDevices?.getUserMedia==='function'};
}
function cameraFailureMessage(error){
 const env=cameraEnvironment();
 if(!env.secure)return 'Pelayar tidak menganggap halaman ini sebagai konteks selamat. Akses kamera memerlukan konteks yang dibenarkan, biasanya pautan HTTPS. Fail yang dibuka terus mungkin disekat pada peranti ini. Mod klik/sentuh masih boleh digunakan.';
 if(!env.api)return 'Pelayar atau aplikasi pembuka fail ini tidak menyediakan API kamera. Cuba pelayar penuh melalui pautan HTTPS. Fail tempatan tidak dijamin menyokong kamera pada semua telefon dan tablet.';
 if(error.message==='MODEL_LOAD_FAILED')return 'Kamera berjaya dibuka, tetapi model AI gagal dimuatkan. Model memerlukan internet dan akses ke jsDelivr serta Google Storage. Mod klik/sentuh masih tersedia.';
 if(error.name==='NotAllowedError'||error.name==='SecurityError')return 'Akses kamera tidak dibenarkan. Semak kebenaran kamera Chrome dalam tetapan Android dan Site settings > Camera. Konteks fail atau polisi peranti juga boleh menyekat akses walaupun kebenaran aplikasi telah diberi.';
 if(error.name==='NotFoundError')return 'Tiada kamera yang sesuai ditemui. Semak kamera peranti, kemudian cuba lagi.';
 if(error.name==='NotReadableError'||error.name==='TrackStartError')return 'Kamera tidak dapat dimulakan. Tutup aplikasi lain yang menggunakan kamera, kemudian cuba semula.';
 if(error.name==='OverconstrainedError')return 'Tetapan kamera tidak disokong oleh peranti ini. Cuba kamera lain atau mod sentuh.';
 if(error.message==='VIDEO_PLAY_FAILED')return 'Kamera tersedia tetapi pratonton video gagal dimainkan. Tutup panel, tekan Uji Kamera semula dan kekalkan halaman di hadapan.';
 return 'Kamera belum dapat digunakan. Semak butiran ralat dalam panel Semakan kamera peranti; permainan masih boleh diteruskan dengan sentuhan.';
}
function refreshCameraDiagnostics(error){
 if(error)state.lastCameraError={name:error.name||'Error',message:error.message||''};
 const env=cameraEnvironment();
 const rows=[['Cara halaman dibuka',env.protocol],['Konteks selamat',env.secure?'Ya':'Tidak'],['API kamera tersedia',env.api?'Ya':'Tidak'],['Stream kamera',state.cameraReady?'Aktif':'Belum aktif'],['Model AI',state.aiModelsReady?'Sedia':'Belum sedia']];
 if(state.lastCameraError)rows.push(['Ralat terakhir',state.lastCameraError.name+' · '+state.lastCameraError.message]);
 document.querySelectorAll('.camera-diagnostic-content').forEach(el=>{
  el.replaceChildren();
  const lead=document.createElement('p');lead.textContent='Semakan ini tidak mengaktifkan kamera. Nilai ini dibaca pada peranti anda.';el.append(lead);
  rows.forEach(([label,value])=>{const row=document.createElement('div');const key=document.createElement('span');const val=document.createElement('b');key.textContent=label;val.textContent=value;row.append(key,val);el.append(row);});
  const note=document.createElement('p');note.className='camera-diagnostic-note';note.textContent=!env.secure||!env.api?'Akses kamera belum tersedia dalam konteks ini. Mod klik/sentuh tetap boleh digunakan.':'API tersedia; ini belum mengesahkan kebenaran kamera, fungsi kamera fizikal atau muat turun model. Tekan Uji Kamera & AI untuk menguji.';el.append(note);
 });
}
function makeCameraDiagnostics(){const details=document.createElement('details');details.className='camera-diagnostics';const summary=document.createElement('summary');summary.textContent='Semakan kamera peranti';const content=document.createElement('div');content.className='camera-diagnostic-content';details.append(summary,content);details.addEventListener('toggle',()=>{if(details.open)refreshCameraDiagnostics();});return details;}
document.querySelector('.control-choice').after(makeCameraDiagnostics());
document.querySelector('#modal-camera-debug>div').append(makeCameraDiagnostics());
const originalCameraStart=startCameraAndAI;
startCameraAndAI=async function(){state.lastCameraError=null;refreshCameraDiagnostics();try{return await originalCameraStart();}finally{refreshCameraDiagnostics();}};
refreshCameraDiagnostics();

