const NG={version:3,baseURL:'https://wriizo212.github.io/pome-questure/',history:[],metrics:{bod:25000,do:1.2,gas:0},target:{bod:25000,do:1.2,gas:0},economics:{capex:18000000,tariff:.35,availability:85,opex:900000,power:2},crisis:null,bossSummary:null,qrURL:'',qrMatrix:null,reportId:'',cursorEnabled:false};
window.POME_NG=NG;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const ngMoney=v=>'RM '+Math.round(v).toLocaleString('ms-MY');
function ngEl(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;}
const crisisScreen=ngEl('section');crisisScreen.id='screen-crisis';crisisScreen.hidden=true;
