function finishNGCertificate(){originalFinalNG();document.querySelectorAll('.boss-result-line').forEach(e=>e.remove());const b=NG.bossSummary;if(b){const line=ngEl('div','boss-result-line',`Boss Monsun: ${b.success?'Berjaya':'Perlu penambahbaikan'} · ${b.score}/100 · Stabil ${b.stable}s · Paras puncak ${b.peak}% · Kuiz ${state.score}/140.`);$('screen-certificate').prepend(line);}if(typeof makeScoreCard==='function')makeScoreCard();}
$('btn-crisis-finish').addEventListener('click',finishNGCertificate);
const practice=ngEl('button','boss-launch tool-button','ϟ Latihan Boss Monsun');practice.type='button';practice.id='btn-boss-practice';practice.addEventListener('click',()=>{if(NG.crisis?.phase==='running'){premiumToast('Selesaikan krisis semasa dahulu.');return;}startBoss(true);});document.querySelector('header>div>div:last-child').prepend(practice);
const ngSaveBase=saveCheckpoint;
saveCheckpoint=function(){const ok=ngSaveBase();if(ok){const data=storageGet(CHECKPOINT,null);if(data){data.ng={history:NG.history.slice(-90),economics:NG.economics,bossSummary:NG.bossSummary};storageSet(CHECKPOINT,data);}}return ok;};
$('btn-resume').addEventListener('click',()=>{const data=state.ng;if(data){if(Array.isArray(data.history))NG.history=data.history.filter(p=>Number.isFinite(p.bod)).slice(-90);if(data.economics){for(const k of ['capex','tariff','availability'])if(Number.isFinite(data.economics[k]))NG.economics[k]=data.economics[k];$('econ-capex').value=clamp(NG.economics.capex/1e6,5,40);$('econ-tariff').value=clamp(NG.economics.tariff,.1,.8);$('econ-availability').value=clamp(NG.economics.availability,40,95);updateEconomics();}NG.bossSummary=data.bossSummary||null;}updateEnvironmentalTelemetry();});
$('btn-start-game').addEventListener('click',()=>{NG.crisis=null;NG.bossSummary=null;NG.history=[];NG.metrics={bod:25000,do:1.2,gas:0};NG.target={...NG.metrics};NG.reportId='';state.ng=null;pushTelemetry();},true);
