function scoreChecksum(text){let h=2166136261;for(let i=0;i<text.length;i++)h=Math.imul(h^text.charCodeAt(i),16777619);return (h>>>0).toString(16).padStart(8,'0');}
function encodeScore(obj){const text=JSON.stringify(obj),bytes=new TextEncoder().encode(text),b64=btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');return b64+'.'+scoreChecksum(text);}
function decodeScore(token){if(token.length>6000)throw new Error('Rekod terlalu panjang');const [encoded,check]=token.split('.');if(!encoded||!check)throw new Error('Format tidak lengkap');let b64=encoded.replace(/-/g,'+').replace(/_/g,'/');b64+='='.repeat((4-b64.length%4)%4);const text=new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(atob(b64),c=>c.charCodeAt(0)));if(scoreChecksum(text)!==check)throw new Error('Checksum tidak sepadan');const data=JSON.parse(text);const count=data.v===2?5:data.q?.[4];if(![2,3].includes(data.v)||![5,10].includes(count)||typeof data.n!=='string'||data.n.length>180||typeof data.c!=='string'||data.c.length>180||!Array.isArray(data.q)||data.q.length!==(data.v===2?4:5)||!data.q.every(Number.isInteger)||data.q[0]<0||data.q[0]>140||data.q[1]<0||data.q[1]>count||data.q[2]<0||data.q[2]>count||data.q[3]<0||data.q[3]>2||data.q[0]!==(50/count)*(data.q[1]+data.q[2])+20*data.q[3]||!Array.isArray(data.e)||data.e.length!==4||!data.e.every(Number.isFinite)||data.e[0]<5e6||data.e[0]>4e7||data.e[1]<.1||data.e[1]>.8||data.e[2]<40||data.e[2]>95||data.e[3]!==900000||typeof data.id!=='string'||data.id.length>50||typeof data.d!=='string'||data.d.length>40||!Array.isArray(data.b)||data.b.length!==6||!data.b.every(Number.isFinite)||data.b[0]<0||data.b[0]>1||data.b[1]<0||data.b[1]>100||data.b[2]<0||data.b[2]>45||data.b[3]<0||data.b[3]>105||data.b[4]<0||data.b[4]>45)throw new Error('Julat rekod tidak sah');return data;}
function scoreData(){if(!NG.reportId){const random=new Uint32Array(1);crypto.getRandomValues(random);NG.reportId='PQ-'+new Date().toISOString().slice(0,10).replace(/-/g,'')+'-'+random[0].toString(16).slice(0,6).toUpperCase();NG.reportTime=new Date().toISOString();}const b=NG.bossSummary||{success:false,score:0,stable:0,peak:0,elapsed:0,attempt:0};return {v:3,id:NG.reportId,n:(state.studentName||'Jurutera Muda').slice(0,180),c:(state.studentClass||'').slice(0,180),q:[state.score,state.stageScores.s1,state.stageScores.s2,state.stageScores.s3,QUESTIONS_STAGE_1.length],b:[b.success?1:0,b.score,b.stable,b.peak,b.elapsed,b.attempt],e:[NG.economics.capex,NG.economics.tariff,NG.economics.availability,NG.economics.opex],d:NG.reportTime};}
function refreshScoreQR(){const data=scoreData(),token=encodeScore(data);NG.qrURL=NG.baseURL+'#score='+token;const qr=qrcode(0,'M');qr.addData(NG.qrURL,'Byte');qr.make();NG.qrMatrix=qr;paintQR($('score-qr-canvas'),qr);$('score-card-id').textContent=data.id+' · '+data.n+' · '+data.q[0]+'/140';return data;}
function paintQR(canvas,qr){const count=qr.getModuleCount(),cell=4,size=(count+8)*cell;canvas.width=size;canvas.height=size;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,size,size);ctx.fillStyle='#10251b';for(let r=0;r<count;r++)for(let c=0;c<count;c++)if(qr.isDark(r,c))ctx.fillRect((c+4)*cell,(r+4)*cell,cell,cell);}
const baseCertificateNG=drawCertificateCanvas;
drawCertificateCanvas=function(){baseCertificateNG();const c=$('certificate-canvas'),copy=document.createElement('canvas');copy.width=c.width;copy.height=c.height;copy.getContext('2d').drawImage(c,0,0);c.height=1220;const ctx=c.getContext('2d');ctx.drawImage(copy,0,0);ctx.fillStyle='#f1f1df';ctx.fillRect(0,840,1200,380);ctx.fillStyle='#173d31';ctx.fillRect(0,1200,1200,20);refreshScoreQR();const q=$('score-qr-canvas'),size=300;ctx.imageSmoothingEnabled=false;ctx.drawImage(q,60,866,size,size);ctx.imageSmoothingEnabled=true;ctx.textAlign='left';ctx.fillStyle='#254e36';ctx.font='800 19px "Plus Jakarta Sans",sans-serif';ctx.fillText('KAD SKOR QR / ANALISIS KEJURUTERAAN',390,892);ctx.font='12px "Plus Jakarta Sans",sans-serif';ctx.fillStyle='#647a58';ctx.fillText(NG.reportId,390,918);
 const e=economicResults(),b=NG.bossSummary;const lines=[b?`Boss Monsun: ${b.success?'Berjaya':'Perlu penambahbaikan'} | ${b.score}/100 | stabil ${b.stable}s`:'Boss Monsun: belum dilengkapkan',`CAPEX ${ngMoney(NG.economics.capex)} | Biogas 2 MW | tersedia ${NG.economics.availability}%`,`Tenaga ${(e.energy/1e6).toFixed(2)} GWh/tahun | hasil ${ngMoney(e.revenue)}/tahun`,`Aliran bersih ${ngMoney(e.net)}/tahun | ROI mudah ${e.roi.toFixed(1)}%`,`Pulang modal: ${e.payback?e.payback.toFixed(1)+' tahun':'tiada aliran bersih positif'} | tarif RM ${NG.economics.tariff.toFixed(2)}/kWh`];ctx.font='600 15px "Plus Jakarta Sans",sans-serif';ctx.fillStyle='#2d523b';lines.forEach((line,i)=>ctx.fillText(line,390,953+i*33,740));ctx.font='11px "Plus Jakarta Sans",sans-serif';ctx.fillStyle='#7a8768';ctx.fillText('Model pembelajaran; bukan ramalan kewangan. OPEX andaian RM 900,000/tahun.',390,1138);ctx.fillText('QR: semakan data kendiri dengan checksum; bukan pengesahan rasmi pelayan.',390,1160);};
