function displayScoreToken(){const match=location.hash.match(/^#score=(.+)$/);if(!match)return;const fields=$('verify-fields');fields.replaceChildren();try{const d=decodeScore(match[1]);$('verify-title').textContent='Checksum sepadan';$('verify-summary').textContent='Rekod '+d.id+' · '+new Date(d.d).toLocaleString('ms-MY');const e=economicResults({capex:d.e[0],tariff:d.e[1],availability:d.e[2],opex:d.e[3],power:2});for(const [k,v] of [['Nama pelajar',d.n],['Kelas',d.c],['Kuiz',d.q[0]+'/140'],['Boss Monsun',(d.b[0]?'Berjaya':'Perlu penambahbaikan')+' · '+d.b[1]+'/100'],['Tempoh stabil',d.b[2]+'s'],['Paras puncak',d.b[3]+'%'],['CAPEX andaian',ngMoney(d.e[0])],['ROI / pulang modal',e.roi.toFixed(1)+'% / '+(e.payback?e.payback.toFixed(1)+' tahun':'tiada')]]){const pair=ngEl('div');pair.append(ngEl('dt',null,k),ngEl('dd',null,v));fields.append(pair);}}catch(err){$('verify-title').textContent='Rekod tidak dapat disahkan';$('verify-summary').textContent='Data tidak lengkap, checksum tidak sepadan atau nilai di luar julat model. Minta semula kad skor asal.';}scoreView.classList.add('open');$('btn-close-score-view').focus();}
