function wrapReport(ctx,text,x,y,maxWidth,lineHeight){let line='';for(const word of String(text).split(/\s+/)){const test=line?line+' '+word:word;if(ctx.measureText(test).width>maxWidth&&line){ctx.fillText(line,x,y);y+=lineHeight;line=word;}else line=test;}if(line){ctx.fillText(line,x,y);y+=lineHeight;}return y;}
function reportPage(title,page){const c=document.createElement('canvas');c.width=1240;c.height=1754;const ctx=c.getContext('2d');ctx.fillStyle='#f3f4e8';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#173d31';ctx.fillRect(0,0,c.width,25);ctx.fillStyle='#244d37';ctx.font='800 22px "Plus Jakarta Sans",sans-serif';ctx.fillText('POME QUESTURE / MONSOON EDITION',75,90);ctx.font='800 42px "Plus Jakarta Sans",sans-serif';ctx.fillText(title,75,165);ctx.fillStyle='#829374';ctx.font='17px "Plus Jakarta Sans",sans-serif';ctx.fillText(NG.reportId+' · SBV60104 / CLO3',75,205);ctx.font='14px sans-serif';ctx.fillText('Model pembelajaran konseptual · '+page+'/2',75,1695);ctx.fillText('Rekod kendiri; perlu disemak bersama evidens kelas.',75,1720);return {c,ctx};}
function makeReportPages(){refreshScoreQR();const e=economicResults(),b=NG.bossSummary;const first=reportPage('Laporan analisis kejuruteraan',1),ctx=first.ctx;let y=275;ctx.fillStyle='#1b422f';ctx.font='800 30px "Plus Jakarta Sans",sans-serif';y=wrapReport(ctx,state.studentName||'Jurutera Muda',75,y,1060,40);ctx.font='19px "Plus Jakarta Sans",sans-serif';ctx.fillStyle='#66805b';y=wrapReport(ctx,state.studentClass,75,y+10,1060,27)+35;
 const sections=[['PENCAPAIAN KUANTITATIF',`Kuiz: ${state.score}/140. Peringkat 1: ${state.stageScores.s1}/${QUESTIONS_STAGE_1.length}. Peringkat 2: ${state.stageScores.s2}/${QUESTIONS_STAGE_2.length}. Dua misi reka bentuk: ${state.stageScores.s3}/2.`,b?`Krisis monsun: ${b.success?'berjaya':'perlu penambahbaikan'}, ${b.score}/100. Masa aktif ${b.elapsed}s, stabil ${b.stable}s, paras puncak ${b.peak}%, paras akhir ${b.final}%.`:'Krisis belum dilengkapkan.'],['ANDAIAN MODEL 2 MW',`CAPEX ${ngMoney(NG.economics.capex)}. Tarif RM ${NG.economics.tariff.toFixed(2)}/kWh. Ketersediaan ${NG.economics.availability}%. OPEX ${ngMoney(NG.economics.opex)}/tahun.`,`Tenaga = 2,000 kW × 8,760 jam × ${NG.economics.availability}%. Tenaga tahunan ${(e.energy/1e6).toFixed(3)} GWh. Hasil kasar ${ngMoney(e.revenue)}/tahun; aliran bersih ${ngMoney(e.net)}/tahun.`],['CAPEX / ROI / KEPUTUSAN',`ROI mudah = aliran bersih ÷ CAPEX × 100 = ${e.roi.toFixed(2)}% setahun. Tempoh pulang modal = CAPEX ÷ aliran bersih = ${e.payback?e.payback.toFixed(2)+' tahun':'tiada pulangan positif'}.`,`Pemulihan tenaga dipilih bersama rawatan POME dan guna semula air. Anggaran ini tidak mengambil kira cukai, pembiayaan, degradasi, hasil haba atau kos pelupusan pekatan RO. Nilai ini bukan sebut harga atau nasihat pelaburan.`]];
 for(const [heading,...paragraphs] of sections){ctx.fillStyle='#274f35';ctx.font='800 17px "Plus Jakarta Sans",sans-serif';ctx.fillText(heading,75,y);y+=36;ctx.fillStyle='#516a48';ctx.font='19px "Plus Jakarta Sans",sans-serif';for(const p of paragraphs)y=wrapReport(ctx,p,75,y,1080,29)+16;y+=20;}
 ctx.drawImage($('score-qr-canvas'),75,Math.max(y,1270),250,250);ctx.fillStyle='#6c805c';ctx.font='17px sans-serif';wrapReport(ctx,'Imbas untuk membuka kad skor. Checksum menyemak kesepadanan data sahaja; identiti dan keputusan rasmi perlu disahkan oleh pensyarah.',355,Math.max(y,1270)+35,780,28);
 const second=reportPage('Jejak keputusan & pemulihan',2),c2=second.ctx;const chart=document.createElement('canvas');chart.width=1050;chart.height=310;chart.style.width='1050px';chart.style.height='310px';paintTelemetry(chart);c2.fillStyle='#0c2422';c2.fillRect(75,255,1090,330);c2.drawImage(chart,95,265,1050,310);c2.fillStyle='#5a7450';c2.font='17px sans-serif';c2.fillText('Skala relatif: BOD / 25,000 · DO / 8 · biogas / 2.2. Sampel model, bukan bacaan sensor.',75,620);c2.fillStyle='#234d32';c2.font='800 18px sans-serif';c2.fillText('DEBRIEF KRISIS MONSUN',75,690);c2.font='18px sans-serif';c2.fillStyle='#5a7450';let y2=735;
 if(b){const summary=`Aliran masuk +200% (3× normal). Sasaran: 38°C ±2°C, pH 7.0 ±0.3, pam RO ≥80%. Keputusan: ${b.success?'Berjaya':'Perlu penambahbaikan'}. Skor kemahiran ${b.score}/100 berasingan daripada kuiz.`;y2=wrapReport(c2,summary,75,y2,1080,29)+30;for(const entry of (b.log||[]).slice(-13))y2=wrapReport(c2,entry.time.toFixed(1)+'s — '+entry.text,75,y2,1080,27)+8;}else y2=wrapReport(c2,'Belum ada log krisis.',75,y2,1080,27);
 c2.fillStyle='#234d32';c2.font='800 18px sans-serif';c2.fillText('REFLEKSI CLO3',75,Math.max(y2+30,1320));c2.fillStyle='#5a7450';c2.font='18px sans-serif';wrapReport(c2,'Bincangkan: Mengapa pam RO sahaja tidak mencukupi apabila suhu dan pH tidak sesuai? Apakah perubahan CAPEX, tarif dan ketersediaan yang menukar tempoh pulang modal? Bagaimanakah teknologi rawatan mengurangkan pencemaran sambil memulihkan sumber?',75,Math.max(y2+70,1360),1080,30);return [first.c,second.c];}
function canvasesToPDF(pages){const encoder=new TextEncoder(),chunks=[],offsets=[0];let length=0;const add=v=>{const bytes=typeof v==='string'?encoder.encode(v):v;chunks.push(bytes);length+=bytes.length;};const object=(id,content)=>{offsets[id]=length;add(id+' 0 obj\n');add(content);add('\nendobj\n');};add('%PDF-1.4\n%POME\n');object(1,'<< /Type /Catalog /Pages 2 0 R >>');object(2,'<< /Type /Pages /Count '+pages.length+' /Kids ['+pages.map((_,i)=>(3+i*3)+' 0 R').join(' ')+'] >>');pages.forEach((canvas,i)=>{const pageId=3+i*3,imgId=pageId+1,streamId=pageId+2,jpeg=Uint8Array.from(atob(canvas.toDataURL('image/jpeg',.92).split(',')[1]),c=>c.charCodeAt(0));object(pageId,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /XObject << /Im${i} ${imgId} 0 R >> >> /Contents ${streamId} 0 R >>`);offsets[imgId]=length;add(imgId+' 0 obj\n<< /Type /XObject /Subtype /Image /Width '+canvas.width+' /Height '+canvas.height+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+jpeg.length+' >>\nstream\n');add(jpeg);add('\nendstream\nendobj\n');const commands=`q 595.28 0 0 841.89 0 0 cm /Im${i} Do Q\n`;object(streamId,'<< /Length '+commands.length+' >>\nstream\n'+commands+'endstream');});const start=length,count=3+pages.length*3;add('xref\n0 '+count+'\n0000000000 65535 f \n');for(let i=1;i<count;i++)add(String(offsets[i]).padStart(10,'0')+' 00000 n \n');add('trailer\n<< /Size '+count+' /Root 1 0 R >>\nstartxref\n'+start+'\n%%EOF');return new Blob(chunks,{type:'application/pdf'});}
$('btn-export-engineering-pdf').addEventListener('click',()=>{try{const blob=canvasesToPDF(makeReportPages()),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Laporan_POME_'+NG.reportId+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);premiumToast('Laporan PDF dua halaman disediakan.');}catch(err){console.error(err);premiumToast('Laporan gagal dijana. Cuba semula selepas halaman selesai dimuatkan.');}});

// Original questions plus 30 new, independently authored SMK-context questions.
const ACADEMY_NEW_1=[
 ['green-purpose','T4 · 4.1 Teknologi Hijau','Asas','Apakah matlamat utama teknologi hijau apabila digunakan untuk merawat air sisa kilang?',['Mengurangkan kesan negatif kepada alam sekitar sambil menggunakan sumber dengan cekap','Menyembunyikan warna air sisa tanpa merawatnya','Menambahkan penggunaan bahan api fosil bagi setiap unit produk','Memindahkan semua pencemar dari sungai ke udara'],0,'Teknologi hijau menilai kesan keseluruhan: pencemaran dikurangkan, sumber dijimatkan dan kegunaan baharu dipulihkan. Air yang kelihatan jernih sahaja belum membuktikan rawatan mencukupi.'],
 ['renewable','T4 · 4.2 Sektor Tenaga','Asas','Yang manakah contoh sumber tenaga boleh baharu dalam konteks kilang sawit?',['Diesel yang diimport','Biogas daripada penguraian sisa organik yang diurus secara lestari','Arang batu daripada lombong','Gas petroleum cecair daripada petroleum'],1,'Sisa organik ialah biojisim yang boleh diperbaharui. Biogas boleh memulihkan sebahagian tenaga kimianya. Pengurusan lestari masih diperlukan; boleh baharu tidak bermaksud tiada kesan alam sekitar.'],
 ['bod-do','T5 · 3.2 Pencemaran air','Memahami','Apakah perbezaan paling tepat antara BOD dengan oksigen terlarut (DO)?',['BOD mengukur suhu, manakala DO mengukur pH','Kedua-duanya ialah nama lain bagi warna air','BOD ialah keperluan oksigen untuk penguraian biologi; DO ialah oksigen yang tersedia dalam air','DO ialah jumlah minyak dan BOD ialah jumlah garam'],2,'Ingat: BOD = oksigen yang diminta oleh proses penguraian; DO = oksigen yang ada dalam air. BOD tinggi boleh menyebabkan penggunaan DO meningkat jika bekalan oksigen tidak mencukupi.'],
 ['eutrophication','T5 · 3.2 Pencemaran air','Menganalisis','Baja berlebihan mengalir ke tasik. Alga bertambah, kemudian banyak ikan mati. Apakah penjelasan yang paling munasabah?',['Semua alga menghasilkan racun yang sama','Air tasik bertukar menjadi asid kuat secara automatik','Ikan tidak dapat berenang kerana air menjadi lebih berat','Apabila alga mati, pengurai menggunakan oksigen lalu DO boleh menurun'],3,'Nutrien berlebihan boleh menyebabkan eutrofikasi. Pereputan biojisim alga meningkatkan penggunaan oksigen. Perhatikan urutan sebab → kesan, bukan sekadar warna hijau air.'],
 ['not-drink','T5 · 3.2 Pencemaran air','Memahami','Sampel air selepas rawatan kelihatan jernih. Apakah kesimpulan yang paling selamat secara saintifik?',['Air itu pasti sesuai diminum','Ujian lain masih diperlukan kerana kejernihan tidak membuktikan air bebas patogen atau bahan terlarut berbahaya','BOD sampel itu mesti sifar','Air itu tidak mengandungi sebarang garam mineral'],1,'Kejernihan hanya pemerhatian fizikal. Kualiti air perlu dinilai menggunakan parameter yang bersesuaian, termasuk mikrobiologi dan kimia. Model permainan ini tidak mengesahkan air minuman.'],
 ['carbon-footprint','T5 · 3.1 Jejak karbon','Asas','Apakah maksud jejak karbon?',['Hanya kesan tapak kasut di tanah','Jumlah karbon yang terdapat dalam satu pokok sahaja','Jumlah pelepasan gas rumah hijau yang berkaitan dengan sesuatu aktiviti atau produk','Jumlah semua oksigen dalam atmosfera'],2,'Jejak karbon merangkumi pelepasan berkaitan aktiviti atau kitar hayat produk. Memulihkan tenaga dan menjimatkan penggunaan sumber boleh membantu mengurangkannya, bergantung pada keadaan sebenar.'],
 ['efficiency','T4 · 4.1 Kecekapan tenaga','Mengaplikasi','Dua pam memindahkan isipadu air yang sama ke ketinggian yang sama. Pam P menggunakan 4 kWh, manakala pam Q menggunakan 6 kWh. Pam manakah lebih cekap untuk tugas ini?',['Pam P, kerana menggunakan kurang tenaga bagi tugas yang sama','Pam Q, kerana menggunakan lebih banyak tenaga','Kedua-duanya pasti sama cekap','Tidak boleh dibandingkan walaupun tugas dan hasilnya sama'],0,'Bandingkan tenaga input bagi hasil berguna yang sama. Dalam situasi ini, pam P menggunakan 2 kWh kurang tenaga. Kecekapan bukan sekadar saiz atau harga mesin.'],
 ['fair-test','Kemahiran proses sains · Pemboleh ubah','Mengaplikasi','Murid mengkaji kesan suhu terhadap aktiviti kultur mikroorganisma yang sama. Apakah pemboleh ubah dimanipulasikan?',['Isipadu sampel yang dikekalkan sama','Jenis bekas yang digunakan','Tempoh pemerhatian yang dikekalkan sama','Suhu kultur'],3,'Pemboleh ubah dimanipulasikan ialah faktor yang sengaja diubah. Faktor lain seperti pH, isipadu dan jenis kultur dikawal supaya perubahan respons dapat dikaitkan dengan suhu.'],
 ['graph-interpret','T5 · 3.2 Tafsiran data air','Menganalisis','Selepas rawatan, graf menunjukkan BOD menurun daripada 25,000 kepada 2,500 mg/L. Berapakah peratus pengurangan BOD?',['10%','90%','50%','100%'],1,'Pengurangan = (25,000 − 2,500) ÷ 25,000 × 100 = 90%. Nilai akhir masih bukan sifar, maka rawatan tambahan mungkin diperlukan mengikut tujuan air tersebut.'],
 ['ph-neutral','Asas SMK · Asid dan alkali','Asas','Larutan model POME mempunyai pH 4.2. Apakah sifat larutan itu?',['Neutral','Beralkali','Berasid','pH tidak boleh digunakan untuk membandingkan keasidan'],2,'Pada skala pH lazim, pH di bawah 7 menunjukkan sifat berasid. Nilai pH ialah ukuran keasidan/kealkalian, bukan ukuran terus jumlah bahan organik atau BOD.'],
 ['waste-priority','T4 · 4.3 Pengurusan sisa','Menilai','Apakah tindakan paling baik untuk mengurangkan pencemaran sebelum menambah sistem rawatan di hujung proses?',['Mencegah pembaziran dan mengurangkan sisa di punca','Mencairkan semua sisa dengan lebih banyak air bersih','Memindahkan sisa ke sungai yang lebih besar','Menambah pewarna agar sisa kurang kelihatan'],0,'Mencegah dan mengurangkan sisa di punca mengurangkan beban rawatan. Rawatan dan pemulihan sumber melengkapkan pendekatan ini, bukannya menggantikan usaha mengurangkan sisa.'],
 ['sample-evidence','Kemahiran proses sains · Bukti','Menilai','Untuk membandingkan dua kaedah rawatan air, data manakah paling membantu?',['Warna cat tangki rawatan','Bilangan poster tentang alam sekitar','Pendapat seorang pemerhati sahaja','Bacaan BOD/DO sebelum dan selepas rawatan bagi sampel dan keadaan yang setara'],3,'Perbandingan memerlukan ukuran yang berkaitan, keadaan terkawal dan ulangan yang sesuai. Bukti kuantitatif lebih kukuh daripada rupa mesin atau slogan.'],
 ['biomass','T4 · 4.2 Tenaga biojisim','Asas','Apakah yang dimaksudkan dengan biojisim dalam konteks tenaga?',['Hanya gas yang terdapat dalam udara','Bahan organik daripada organisma atau sisanya yang boleh menjadi sumber tenaga','Semua mineral dalam batuan','Air tulen tanpa sebarang bahan organik'],1,'Sisa tumbuhan dan bahan organik ialah contoh biojisim. Tenaga kimia dalam bahan tersebut boleh dipulihkan melalui kaedah yang sesuai, termasuk penghasilan biogas.'],
 ['carbon-cycle','Pengayaan · Kitar karbon','Memahami','Mengapakah karbon dalam sisa organik masih perlu diambil kira apabila menghasilkan biogas?',['Karbon hilang sepenuhnya apabila sisa menjadi gas','Semua karbon bertukar menjadi oksigen','Karbon berpindah antara bahan organik, gas dan persekitaran; kebocoran serta pelepasan masih perlu diurus','Biogas tidak mengandungi sebatian karbon'],2,'Bahan tidak lenyap: unsur karbon berpindah melalui proses biologi dan pembakaran. Memerangkap metana membantu pengurusan pelepasan, tetapi sistem tidak semestinya sifar pelepasan.'],
 ['palm-sustain','T5 · 5.5 Pengurusan sawit lestari','Menilai','Apakah contoh pengurusan industri sawit yang lebih lestari?',['Mengurangkan pembaziran air, merawat efluen dan memulihkan sumber daripada sisa','Menilai kejayaan berdasarkan hasil minyak sahaja','Membakar semua sisa secara terbuka','Melepaskan efluen apabila hujan untuk mencairkannya'],0,'Pengurusan lestari menimbang pengeluaran bersama kesan alam sekitar dan masyarakat. Hujan tidak menghilangkan jumlah pencemar yang dibuang.']
];
const ACADEMY_NEW_2=[
 ['microbe-benefit','T5 · 1.2 Mikroorganisma berfaedah','Asas','Pernyataan manakah betul tentang mikroorganisma?',['Semua mikroorganisma menyebabkan penyakit','Mikroorganisma hanya hidup dalam air kotor','Sebahagian mikroorganisma bermanfaat, termasuk dalam rawatan sisa organik','Mikroorganisma tidak terlibat dalam penguraian'],2,'Mikroorganisma mempunyai peranan pelbagai. Pengurai mengitar semula bahan, manakala kultur yang sesuai boleh digunakan untuk rawatan sisa dan penghasilan biogas.'],
 ['anaerobic','T5 · 1.2 Bioteknologi alam sekitar','Memahami','Apakah maksud keadaan anaerobik dalam proses rawatan biologi?',['Keadaan tanpa oksigen bebas bagi proses tersebut','Keadaan yang mesti tiada air','Keadaan tanpa mikroorganisma','Keadaan yang mesti bersuhu 0°C'],0,'Anaerobik bermaksud tanpa oksigen bebas. Mikroorganisma yang sesuai menjalankan proses biologi dalam keadaan ini. Anaerobik tidak bermaksud semua organisma boleh hidup tanpa oksigen.'],
 ['temperature-optimum','T5 · 1.1 Faktor pertumbuhan mikroorganisma','Menganalisis','Mengapakah suhu reaktor tidak patut dinaikkan tanpa had untuk mempercepat rawatan?',['Semua mikroorganisma membesar paling baik pada suhu mendidih','Suhu tidak mempengaruhi sebarang proses biologi','Suhu tinggi sentiasa menambah oksigen dalam air','Mikroorganisma mempunyai julat suhu sesuai; suhu berlebihan boleh menjejaskan aktiviti dan kelangsungannya'],3,'Suhu optimum bergantung pada jenis mikroorganisma dan proses. Nilai 38°C dalam permainan ialah sasaran model, bukan suhu optimum sejagat untuk semua mikroorganisma.'],
 ['ph-control','Asas SMK · Peneutralan','Mengaplikasi','Dalam model ini, efluen berasid perlu dilaras menghampiri pH 7. Apakah prinsip penggunaan bahan beralkali seperti kapur?',['Menambahkan bahan organik supaya BOD pasti meningkat','Meneutralkan keasidan secara terkawal sambil memantau pH','Menggantikan semua mikroorganisma dalam reaktor','Menghapuskan keperluan menguji air'],1,'Asid dan alkali boleh bertindak balas dalam proses peneutralan. Dos mesti dipantau kerana berlebihan boleh menjadikan keadaan terlalu beralkali. pH sesuai sahaja belum membuktikan semua pencemar telah disingkirkan.'],
 ['energy-transform','T4 · 4.2 Penukaran tenaga','Memahami','Apakah urutan penukaran tenaga yang munasabah bagi penjana elektrik berasaskan biogas?',['Elektrik → cahaya → bahan kimia dalam sisa','Bunyi → nuklear → elektrik','Tenaga kimia biogas → haba dan gerakan enjin/turbin → elektrik','Graviti → makanan → elektrik'],2,'Biogas menyimpan tenaga kimia. Pembakaran membebaskan haba; sistem penjana menukar sebahagian tenaga itu kepada gerakan dan elektrik. Tidak semua tenaga input menjadi elektrik berguna.'],
 ['aeration-role','T5 · 3.2 Rawatan air','Mengaplikasi','Apakah fungsi utama pengudaraan dalam tangki rawatan aerobik?',['Membekalkan oksigen untuk menyokong penguraian aerobik bahan organik','Menambahkan metana terus ke sungai','Menggantikan semua proses penapisan membran','Menurunkan pH ke sifar'],0,'Pengudaraan membantu pemindahan oksigen ke dalam air. Mikroorganisma aerobik menggunakan oksigen untuk menguraikan bahan organik. Reka bentuk dan operasi sebenar menentukan hasil rawatan.'],
 ['ro-concentrate','T5 · 3.2 Teknologi pembersihan air · pengayaan','Menilai','Apakah perkara yang masih perlu diurus selepas penapisan RO?',['Semua air dan pencemar pasti hilang','Air yang ditapis mesti diminum terus tanpa ujian','RO tidak menghasilkan sebarang aliran sampingan','Aliran pekatan yang mengandungi bahan tertahan masih memerlukan pengurusan'],3,'Membran memisahkan aliran: sebahagian air menjadi permeat, manakala bahan tertahan lebih tertumpu dalam pekatan. Teknologi tidak memusnahkan semua pencemar secara automatik.'],
 ['compost','T4 · 4.3 Pemulihan sisa','Memahami','Mengapakah pengkomposan sisa organik secara terkawal boleh membantu kelestarian?',['Ia membenarkan semua sisa dibuang ke mana-mana','Ia memulihkan bahan organik dan nutrien untuk kegunaan yang sesuai','Ia menjamin semua logam berat hilang','Ia menghentikan semua aktiviti mikroorganisma'],1,'Pengkomposan menggunakan proses biologi terkawal untuk memulihkan bahan organik. Kualiti dan keselamatan bahan input serta kompos perlu dinilai sebelum digunakan.'],
 ['ch4-leak','T4 · 4.6 Jejak karbon','Menilai','Sebuah loji menghasilkan biogas tetapi paip metananya bocor. Apakah tindakan paling wajar?',['Biarkan kerana biogas ialah sumber boleh baharu','Tambahkan pewangi pada paip','Mengesan dan membaiki kebocoran serta mengurus gas dengan selamat','Lepaskan lebih banyak gas untuk menurunkan tekanan tanpa kawalan'],2,'Metana ialah gas rumah hijau dan gas mudah terbakar. Pemulihan tenaga mesti disertai kawalan kebocoran serta amalan keselamatan, bukan hanya pemasangan penjana.'],
 ['kwh','T4 · 4.2 Penggunaan tenaga','Mengaplikasi','Sebuah penjana beroperasi pada kuasa 2 MW selama 3 jam. Berapakah tenaga elektrik yang dihasilkan dalam model ideal ini?',['6 MWh','0.67 MWh','5 MW','6 kW'],0,'Tenaga = kuasa × masa. Maka 2 MW × 3 jam = 6 MWh. MW ialah unit kuasa, manakala MWh ialah unit tenaga. Nilai sebenar bergantung pada operasi dan kecekapan.'],
 ['flow-increase','Kemahiran proses sains · Data kuantitatif','Mengaplikasi','Aliran asal ialah 100 unit/minit. Jika aliran MENINGKAT sebanyak 200%, berapakah aliran baharu?',['200 unit/minit','100 unit/minit','50 unit/minit','300 unit/minit'],3,'Tambahan 200% daripada 100 ialah 200. Aliran baharu = 100 + 200 = 300 unit/minit, iaitu tiga kali aliran asal. Bezakan meningkat sebanyak 200% dengan menjadi 200%.'],
 ['systems-thinking','T4 · 4.3 Penyelesaian isu sosiosaintifik','Menilai','Dalam krisis, pam RO ditingkatkan tetapi suhu dan pH kekal tidak sesuai untuk reaktor biologi. Mengapa rawatan keseluruhan mungkin masih lemah?',['Pam yang laju menghapuskan semua syarat biologi','Peringkat rawatan saling bergantung; gangguan biologi meningkatkan beban pada peringkat seterusnya','Semua peringkat rawatan berfungsi secara terasing tanpa kesan antara satu sama lain','Suhu dan pH hanya mempengaruhi warna tangki'],1,'Fikir secara sistem: pra-rawatan, proses biologi dan penapisan saling mempengaruhi. Menguatkan satu peringkat sahaja tidak semestinya menyelesaikan punca gangguan.'],
 ['carbon-handprint','T5 · 3.1 Tapak tangan karbon','Mengaplikasi','Yang manakah contoh tindakan tapak tangan karbon (carbon handprint) yang positif?',['Membazir elektrik untuk menguji had penjana','Membakar sisa secara terbuka supaya kawasan kelihatan bersih','Mengurangkan pembaziran tenaga dan menggalakkan tindakan pengurangan pelepasan yang boleh dinilai','Menggantikan bacaan meter dengan anggaran tanpa rekod'],2,'Tapak tangan karbon merujuk tindakan positif untuk mengurangkan pelepasan. Tindakan yang boleh diukur membantu menilai keberkesanan, berbanding slogan sahaja.'],
 ['resource-evidence','T5 · 3.3 Pemuliharaan sumber','Menganalisis','Loji A dan B merawat jumlah efluen setara. Loji A menggunakan semula 70% air yang sesuai, manakala loji B tiada guna semula. Apakah manfaat yang munasabah bagi loji A?',['Keperluan air baharu boleh berkurang, tertakluk pada kualiti dan kegunaan air pulih','Loji A tidak perlu memantau kualiti air lagi','Loji A pasti tidak menghasilkan sebarang sisa lain','Air pulih mesti sesuai untuk semua kegunaan'],0,'Guna semula boleh menjimatkan sumber air, tetapi kesesuaian bergantung pada tujuan dan kualiti air. Peratus pemulihan bukan jaminan bahawa semua kegunaan adalah selamat.'],
 ['sustainable-choice','T4 · 4.1 Tonggak kelestarian','Menilai','Apakah pertimbangan yang paling lengkap ketika memilih teknologi rawatan untuk komuniti?',['Kos pembelian paling rendah sahaja','Rupa bangunan yang paling moden sahaja','Jumlah iklan tentang teknologi tersebut','Kesan alam sekitar, kos dan penyelenggaraan, serta manfaat dan keselamatan masyarakat'],3,'Keputusan lestari menimbang alam sekitar, ekonomi dan sosial. Sistem yang mahal atau canggih tidak semestinya paling sesuai jika tidak dapat dikendalikan dan disenggara dengan baik.']
];
const ACADEMY_LESSONS=[
 {id:'pome',icon:'◉',title:'POME: dari mana datangnya?',tag:'T4 4.3 · T5 5.5',time:'3 min',hook:'Air sisa bukan sekadar “air kotor”. Ia membawa bahan, haba dan tenaga.',body:['POME bermaksud Palm Oil Mill Effluent, iaitu efluen daripada pemprosesan minyak sawit. Air ini boleh mengandungi bahan organik, minyak dan pepejal terampai. Apabila bahan organik terurai, mikroorganisma menggunakan sumber dan mengubah keadaan persekitaran.','Bezakan tiga pemerhatian: suhu memberitahu keadaan haba; pH memberitahu keasidan atau kealkalian; BOD membantu menunjukkan keperluan oksigen berkaitan penguraian biologi. Satu bacaan tidak menggantikan bacaan yang lain.','Dalam permainan, sampel awal diwakili oleh 85°C, pH 4.2 dan BOD 25,000 mg/L. Ini contoh model untuk membandingkan keadaan, bukan nilai tetap bagi setiap kilang. Pengurusan lestari bermula dengan mengurangkan pembaziran air dan sisa di punca sebelum merawat efluen.'],memory:'3S sebelum rawat: Sifat haba · Sifat asid · Sisa organik.',misconception:'“Air yang cair atau kurang berwarna sudah tidak mencemar.” Jumlah pencemar boleh kekal walaupun dicairkan.',prompt:'Mengapakah hujan lebat tidak menghapuskan jumlah bahan pencemar?',answer:'Pencairan boleh mengurangkan kepekatan tetapi tidak semestinya mengurangkan jumlah bahan pencemar. Aliran yang lebih besar juga boleh melebihi kapasiti rawatan.'},
 {id:'oxygen',icon:'≈',title:'BOD vs DO: diminta atau tersedia?',tag:'T5 3.2 · Pencemaran air',time:'4 min',hook:'Bayangkan oksigen dalam sungai sebagai baki wang. DO ialah baki; BOD ialah permintaan untuk membelanjakannya.',body:['DO ialah dissolved oxygen, atau oksigen terlarut yang tersedia dalam air. Ikan dan banyak organisma akuatik memerlukan oksigen ini. BOD ialah biochemical oxygen demand, iaitu keperluan oksigen bagi penguraian biologi bahan organik dalam keadaan ujian tertentu.','Jika beban organik tinggi, proses penguraian boleh menggunakan lebih banyak oksigen. Jika bekalan semula oksigen tidak cukup, DO menurun dan hidupan akuatik boleh terjejas. Hubungan ini dipengaruhi suhu, aliran, pengudaraan dan keadaan ekosistem; ia bukan persamaan tepat untuk semua sungai.','Nutrien berlebihan pula boleh menggalakkan pertumbuhan alga. Apabila biojisim alga mati dan terurai, penggunaan oksigen meningkat. Itulah satu laluan yang boleh menghubungkan eutrofikasi dengan kekurangan oksigen.'],memory:'BOD = oksigen DIMINTA. DO = oksigen yang ADA.',misconception:'“BOD tinggi bermaksud air mempunyai banyak oksigen.” BOD mengukur permintaan, bukan bekalan oksigen.',prompt:'BOD turun 25,000 → 2,500 mg/L. Adakah penurunannya 10% atau 90%?',answer:'90%. Pengurangan = (25,000 − 2,500) ÷ 25,000 × 100. 10% ialah bahagian yang masih tinggal.'},
 {id:'microbes',icon:'✦',title:'Mikroorganisma: pasukan rawatan',tag:'T5 1.1–1.2 · Mikroorganisma',time:'4 min',hook:'Bukan semua mikroorganisma musuh. Ada yang membantu memulihkan sisa menjadi sumber.',body:['Mikroorganisma merangkumi kumpulan organisma yang pelbagai. Sebahagiannya menyebabkan penyakit, tetapi banyak juga membantu penguraian, penghasilan makanan dan rawatan sisa. Kultur yang sesuai dipilih mengikut fungsi proses.','Proses aerobik menggunakan oksigen bebas. Proses anaerobik berlaku tanpa oksigen bebas bagi proses tersebut. Dalam sistem biogas, beberapa kumpulan mikroorganisma bekerjasama menguraikan bahan organik; mikroorganisma metanogen menyumbang kepada penghasilan metana. Metanogen bukan alasan untuk menganggap semua mikroorganisma boleh hidup tanpa oksigen.','Suhu, pH, nutrien dan keadaan persekitaran mempengaruhi aktiviti mikroorganisma. Setiap kultur mempunyai julat yang sesuai. Sasaran 38°C dan pH 7.0 dalam permainan ialah andaian operasi model, bukan syarat sejagat bagi semua mikroorganisma.'],memory:'Mikrob perlukan keadaan SESUAI, bukan keadaan paling panas atau paling berasid.',misconception:'“Lebih panas sentiasa lebih cepat.” Suhu berlebihan boleh menjejaskan fungsi biologi dan kelangsungan kultur.',prompt:'Jika mengkaji kesan suhu, mengapa pH dan jenis kultur perlu dikekalkan?',answer:'Supaya perbezaan respons boleh dikaitkan dengan suhu. Suhu ialah pemboleh ubah dimanipulasikan; pH dan jenis kultur ialah antara faktor yang dikawal.'},
 {id:'process',icon:'⌘',title:'Empat stesen, satu sistem',tag:'T4 4.3 · Aplikasi teknologi hijau',time:'4 min',hook:'Hafal aliran “Sejuk → Mikrob → Udara → Tapis”, kemudian fahami mengapa urutannya membantu.',body:['1. Pra-rawatan: asingkan bahan yang mengganggu operasi dan laras keadaan efluen. Dalam model ini, efluen disejukkan sebelum masuk ke proses biologi yang dipilih. Penyejukan tidak bermakna semua bahan organik telah disingkirkan.','2. Pencernaan anaerobik: kultur yang sesuai menguraikan bahan organik tanpa oksigen bebas, sambil membolehkan pemulihan biogas. 3. Rawatan aerobik: pengudaraan menyokong penguraian aerobik baki bahan organik. Dua proses ini mempunyai fungsi dan syarat yang berbeza.','4. Pemisahan dan membran: penapisan yang sesuai membantu menghasilkan aliran air pulih untuk kegunaan yang ditentukan. RO menghasilkan permeat serta aliran pekatan. Pekatan dan enap cemar masih perlu diurus; bahan pencemar tidak hilang secara ajaib. Reka bentuk sebenar boleh mempunyai lebih banyak stesen daripada model ini.'],memory:'S–M–U–T: Sejukkan · Mikrob · Udarakan · Tapis.',misconception:'“RO sahaja menyelesaikan semua masalah.” Gangguan di hulu boleh menambah beban dan menjejaskan proses hiliran.',prompt:'Mengapakah menaikkan pam RO sahaja mungkin gagal menyelamatkan loji yang terlalu panas?',answer:'Jika proses biologi terganggu oleh suhu, beban organik ke hiliran boleh meningkat. Kapasiti pam tidak menggantikan keperluan keadaan biologi yang sesuai.'},
 {id:'energy',icon:'ϟ',title:'Biogas, tenaga dan unit',tag:'T4 4.2 · Pengayaan tenaga',time:'4 min',hook:'MW ialah “seberapa cepat”. MWh ialah “berapa banyak” tenaga sepanjang masa.',body:['Biojisim ialah bahan organik daripada organisma atau sisanya. Dengan proses yang sesuai, sebahagian tenaga kimia dalam sisa dapat dipulihkan. Biogas mengandungi gas seperti metana; komposisinya bergantung pada bahan dan operasi.','Dalam penjana, tenaga kimia bahan api bertukar kepada haba dan gerakan, kemudian sebahagiannya menjadi tenaga elektrik. Terdapat kehilangan dan kegunaan tenaga lain. Sumber boleh baharu tidak bermaksud tiada pelepasan, tiada kos atau tiada risiko kebocoran.','Gunakan tenaga = kuasa × masa. Penjana 2 MW yang beroperasi pada kuasa itu selama 3 jam menghasilkan 6 MWh dalam model ideal. Untuk perbandingan pam, pastikan tugas dan hasil berguna adalah setara sebelum membandingkan penggunaan tenaga.'],memory:'Kuasa × MASA = tenaga. MW × jam = MWh.',misconception:'“Penjana 2 MW menghasilkan 2 MWh dalam sehari.” Ia bergantung pada tempoh dan tahap operasi.',prompt:'Pam P guna 4 kWh dan Q guna 6 kWh untuk tugas sama. Apakah penjimatan relatif apabila memilih P?',answer:'Penjimatan 2 kWh, iaitu (6 − 4) ÷ 6 × 100 ≈ 33.3% berbanding penggunaan Q.'},
 {id:'carbon',icon:'♻',title:'Karbon, 5R dan pilihan lestari',tag:'T4 4.6 · T5 3.1, 3.3',time:'4 min',hook:'Sisa yang dipulihkan masih perlu dilihat sepanjang kitar hayatnya.',body:['Jejak karbon merujuk pelepasan gas rumah hijau yang berkaitan dengan sesuatu aktiviti atau produk. Tapak tangan karbon menekankan tindakan positif untuk mengurangkan pelepasan. Mengukur penggunaan tenaga sebelum dan selepas tindakan membantu menilai hasil sebenar.','Dalam pengurusan sisa, utamakan pencegahan dan pengurangan di punca; kemudian pertimbangkan guna semula, kitar semula dan pemulihan yang sesuai. Dalam kilang, guna semula air yang memenuhi tujuan tertentu boleh mengurangkan keperluan air baharu.','Keputusan lestari menimbang alam sekitar, ekonomi dan sosial. Contohnya, sistem biogas memerlukan kawalan kebocoran dan penyelenggaraan; komuniti memerlukan sungai yang sihat dan operasi yang selamat. Teknologi yang kelihatan canggih tidak semestinya paling sesuai jika tidak dapat dikendalikan dengan baik.'],memory:'Tiga soalan lestari: Baik untuk ALAM? Mampu DIURUS? Baik untuk MASYARAKAT?',misconception:'“Boleh baharu = sifar pelepasan.” Pengangkutan, operasi, kebocoran dan proses lain masih perlu diambil kira.',prompt:'Berikan satu bukti yang lebih kuat daripada slogan “loji hijau”.',answer:'Contohnya rekod pengurangan penggunaan air baharu, kualiti efluen sebelum/selepas rawatan dan pengurangan kebocoran gas, dengan kaedah perbandingan yang munasabah.'},
 {id:'evidence',icon:'↗',title:'Baca graf seperti saintis',tag:'Kemahiran proses sains · KBAT',time:'3 min',hook:'Jangan terus percaya nombor. Tanya unit, cara ukur dan perbandingannya.',body:['Mula dengan mengenal pasti pemboleh ubah serta unit. Dalam permainan, BOD dan DO dipaparkan dalam mg/L, manakala tenaga biogas pada HUD diwakili sebagai kuasa MW. Tiga kuantiti ini tidak boleh dibandingkan terus berdasarkan tinggi garis semata-mata.','Graf telemetri menggunakan skala relatif berasingan yang dilabelkan. BOD menurun menggambarkan pemulihan dalam model; DO dan kuasa biogas boleh meningkat. Nilai model bukan bacaan sensor sungai sebenar dan tidak membuktikan pematuhan peraturan.','Apabila menilai rawatan, bandingkan sampel dan keadaan yang setara, jalankan ulangan yang sesuai dan kenal pasti faktor yang dikawal. Bezakan pemerhatian (“DO menurun”) dengan inferens (“penguraian mungkin menggunakan oksigen lebih cepat daripada bekalan semula”).'],memory:'Sebelum kesimpulan: UNIT → BANDING → BUKTI → SEBAB.',misconception:'“Garis yang paling tinggi sentiasa paling banyak.” Itu tidak benar apabila unit atau skala berlainan.',prompt:'Mengapa dua bacaan daripada dua sungai berlainan belum cukup membuktikan satu teknologi lebih baik?',answer:'Sungai dan keadaan awal mungkin berbeza. Perbandingan memerlukan reka bentuk kajian yang mengambil kira pemboleh ubah lain dan data yang mencukupi.'},
 {id:'crisis',icon:'☂',title:'Strategi monsun & keputusan',tag:'Aplikasi / pengayaan kejuruteraan',time:'3 min',hook:'Tenang: diagnosis punca, laras keadaan, kemudian pantau respons.',body:['Dalam Boss Monsun, “meningkat sebanyak 200%” bermaksud aliran baharu menjadi 300% atau tiga kali aliran asal. Pencairan oleh hujan tidak semestinya mengurangkan jumlah beban pencemar dan aliran besar boleh membebankan kapasiti loji.','Tiga pelaras bekerja dalam satu sistem. Suhu dan pH sebenar mengambil masa untuk menghampiri tetapan. Laras keadaan untuk kultur, kemudian pastikan kapasiti rawatan mencukupi. Pantau paras penimbal dan tempoh stabil; jangan hanya mengejar satu nombor.','Meja CAPEX/ROI ialah pengayaan tentang pertimbangan ekonomi. Model membandingkan kos modal dengan aliran bersih tahunan berdasarkan andaian. Ia tidak merangkumi semua kos dan risiko. Untuk Sains SMK, utamakan hujah saintifik dan pertimbangan alam sekitar, ekonomi serta sosial.'],memory:'DIAGNOSIS → LARAS → TUNGGU RESPONS → PANTAU.',misconception:'“Selepas slider mencapai sasaran, bacaan sebenar terus sama.” Sistem boleh mempunyai kelewatan respons.',prompt:'Apakah maklumat tambahan sebelum keputusan pemasangan loji sebenar?',answer:'Antaranya ciri efluen sebenar, kapasiti, ujian rawatan, kos dan penyelenggaraan, keselamatan, pengurusan aliran sampingan serta syarat pihak berkuasa. Model permainan sahaja tidak mencukupi.'}
];

// SMK academy: session selection is saved, so shuffled answers survive resume.
QUESTIONS_STAGE_1[1].question='Dalam model permainan ini, berapakah BOD awal POME mentah yang digunakan?';
QUESTIONS_STAGE_1[1].options[1]='25,000 mg/L dalam model ini';
QUESTIONS_STAGE_1[1].explanation='Model menggunakan BOD awal 25,000 mg/L untuk menggambarkan beban organik tinggi. Bacaan sebenar berbeza mengikut efluen dan keadaan kilang.';
QUESTIONS_STAGE_1[2].options[2]='Penguraian mikrob menggunakan oksigen terlarut, lalu meningkatkan risiko kematian ikan';
QUESTIONS_STAGE_1[2].explanation='Bahan organik menambah permintaan penguraian. Jika penggunaan oksigen melebihi bekalan semula, DO menurun dan hidupan akuatik boleh terjejas.';
QUESTIONS_STAGE_1[3].explanation='Metana ialah gas rumah hijau. Pelepasan tanpa penangkapan menambah kesan iklim; kolam juga memerlukan ruang dan pengurusan yang sesuai.';
QUESTIONS_STAGE_1[4].question='Dalam model ini, POME mentah bermula pada 85°C dan pH 4.2. Bagaimanakah sifatnya?';
QUESTIONS_STAGE_2[0].options[0]='Gas metana (CH₄), salah satu komponen biogas untuk pemulihan tenaga';
QUESTIONS_STAGE_2[0].explanation='Mikroorganisma metanogen menyumbang kepada penghasilan metana dalam proses anaerobik. Biogas ialah campuran gas; komposisi dan kuasa elektrik yang dapat dipulihkan bergantung pada operasi.';
QUESTIONS_STAGE_2[1].options[1]='Untuk membekalkan oksigen kepada mikroorganisma aerobik bagi mengurangkan baki bahan organik';
QUESTIONS_STAGE_2[1].explanation='Pengudaraan menyokong penguraian aerobik baki bahan organik. Prestasi dan keperluan pelepasan perlu dinilai untuk sistem sebenar; tiada satu bacaan yang menjamin semua aspek keselamatan air.';
QUESTIONS_STAGE_2[2].question='Teknologi manakah membantu menghasilkan aliran air pulih yang boleh dipertimbangkan untuk kegunaan kilang selepas ujian kualiti?';
QUESTIONS_STAGE_2[2].explanation='UF dan RO memisahkan bahan mengikut ciri membran. RO menghasilkan air permeat dan pekatan yang masih perlu diurus. Kadar pemulihan tidak semestinya 100%; air perlu memenuhi spesifikasi kegunaannya.';
QUESTIONS_STAGE_2[3].explanation='Enap cemar dan tandan kosong boleh dipertimbangkan untuk pengkomposan terkawal. Kualiti, kematangan serta kesesuaian kompos perlu dinilai sebelum digunakan.';
QUESTIONS_STAGE_2[4].explanation='Pendekatan bersepadu mengurangkan pencemaran sambil memulihkan tenaga, air atau nutrien yang sesuai. Ia masih memerlukan operasi, penyelenggaraan dan pengurusan sisa baki.';
const academyLegacy=[QUESTIONS_STAGE_1.map(q=>({...q})),QUESTIONS_STAGE_2.map(q=>({...q}))];
const academyBanks=academyLegacy.map((arr,s)=>arr.map((q,i)=>({...q,id:`legacy-${s+1}-${i}`,tag:s?'Aplikasi loji · pengayaan':'Pengenalan POME · pengayaan',difficulty:'Memahami'})).concat((s?ACADEMY_NEW_2:ACADEMY_NEW_1).map(([id,tag,difficulty,question,options,correct,explanation])=>({id,tag,difficulty,category:tag,question,options,correct,explanation}))));
let academySession=null;
function academyShuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let n=new Uint32Array(1);crypto.getRandomValues(n);const j=n[0]%(i+1);[a[i],a[j]]=[a[j],a[i]];}return a;}
function academyConfigure(saved){
 academySession=saved||academyBanks.map(bank=>academyShuffle(bank).slice(0,10).map(q=>({id:q.id,order:academyShuffle([0,1,2,3])})));
 const lists=academySession.map((set,s)=>set.map(item=>{const q=academyBanks[s].find(q=>q.id===item.id);if(!q||item.order.length!==4||new Set(item.order).size!==4||!item.order.every(i=>Number.isInteger(i)&&i>=0&&i<4))throw Error('Sesi soalan tidak sah');return {...q,options:item.order.map(i=>q.options[i]),correct:item.order.indexOf(q.correct)};}));
 if(lists.some(a=>a.length!==10))throw Error('Bilangan soalan tidak sah');QUESTIONS_STAGE_1.splice(0,QUESTIONS_STAGE_1.length,...lists[0]);QUESTIONS_STAGE_2.splice(0,QUESTIONS_STAGE_2.length,...lists[1]);state.questionWeight=5;
}
$('btn-start-game').addEventListener('click',()=>academyConfigure(),true);
$('btn-resume').addEventListener('click',()=>{const d=storageGet(CHECKPOINT,null);try{if(d?.academy)academyConfigure(d.academy);else{[QUESTIONS_STAGE_1,QUESTIONS_STAGE_2].forEach((a,i)=>a.splice(0,a.length,...academyLegacy[i]));academySession=null;state.questionWeight=10;}}catch{academySession=null;premiumToast('Sesi lama tidak serasi. Mulakan misi baharu.');}},true);
const academySave=saveCheckpoint;saveCheckpoint=function(){const ok=academySave();if(ok){const d=storageGet(CHECKPOINT,null);if(d){d.academy=academySession;d.questionWeight=state.questionWeight||5;storageSet(CHECKPOINT,d);}}return ok;};
const academyUpdate=updatePremiumUI;updatePremiumUI=function(){academyUpdate();const total=QUESTIONS_STAGE_1.length+QUESTIONS_STAGE_2.length+2,done=Object.keys(state.answers).length+Object.keys(state.missionCompleted).length;$('mission-position').textContent=`MISI 0${state.stage} / 03 · ${done} DARIPADA ${total} AKTIVITI SELESAI`;$('mission-progress-fill').style.width=done/total*100+'%';toolbar.querySelector('[role=progressbar]').setAttribute('aria-valuemax',total);};
const academyRender=renderCurrentQuestion;renderCurrentQuestion=function(){academyRender();if(state.stage<3){const q=(state.stage===1?QUESTIONS_STAGE_1:QUESTIONS_STAGE_2)[state.questionIndex];$('academy-question-tag').textContent=(q.tag||q.category)+' · '+(q.difficulty||'Pengayaan');}};
const qTag=ngEl('p','academy-question-tag');qTag.id='academy-question-tag';$('options-grid').before(qTag);
const academyHub=ngEl('section','academy-hub');academyHub.id='academy-hub';academyHub.innerHTML=`<div class="academy-heading"><div><span class="academy-eyebrow">AKADEMI SAINS / BELAJAR SEBELUM MISI</span><h2>Dari sisa, kepada solusi.</h2><p>8 nota ringkas berisi · 40 soalan dalam bank · 20 soalan rawak setiap sesi</p></div><span id="academy-reading">0 / 8 nota ditandai dibaca</span></div><p class="academy-scope">Selaras topik Sains KSSM Tingkatan 4–5: Teknologi Hijau, Mikroorganisma, Kelestarian Alam Sekitar dan industri sawit. BOD, membran RO serta ekonomi loji ialah aplikasi / pengayaan. Bukan set soalan rasmi peperiksaan.</p><div class="academy-layout"><nav id="academy-tabs" aria-label="Topik ulang kaji"></nav><article id="academy-lesson"></article></div><div class="academy-experiments"><section><span class="academy-eyebrow">TEROKA SEBAB → KESAN</span><h3>Banyak sisa, apa jadi pada oksigen?</h3><label for="academy-load">Beban sisa organik: <b id="academy-load-label">50%</b></label><input id="academy-load" type="range" min="0" max="100" value="50"><div class="academy-bars"><div>BOD / permintaan <i id="academy-bod"></i></div><div>DO / bekalan <i id="academy-do"></i></div></div><p id="academy-effect"></p><small>Model hubungan kualitatif, bukan ramalan bacaan sungai. DO juga dipengaruhi suhu, pengudaraan, aliran dan fotosintesis.</small></section><section><span class="academy-eyebrow">KAMUS MINI</span><h3>Istilah susah, maksud mudah.</h3><label for="academy-search">Cari istilah</label><input id="academy-search" type="search" placeholder="Contoh: BOD, anaerob, tenaga…"><dl id="academy-glossary"></dl></section></div><details class="academy-references"><summary>Peta topik & rujukan pembelajaran</summary><p>T4 Bab 4: 4.1 Kelestarian, 4.2 Tenaga, 4.3 Pengurusan Sisa dan Air Sisa. T5 Bab 1: Mikroorganisma; Bab 3: Kelestarian Alam Sekitar; Bab 5: Aplikasi industri sawit lestari. Nota ini menggunakan situasi POME sebagai konteks penyelesaian masalah.</p><a href="https://sites.google.com/moe-dl.edu.my/spot-kpm/sekolah-menengah/tingkatan-4/sains/teknologi-hijau-dalam-melestarikan-alam" target="_blank" rel="noopener">Bahan Sains T4: Teknologi Hijau ↗</a> · <a href="https://sites.google.com/moe-dl.edu.my/cgugayahsempoi/utama/sains-kssm/sains-tingkatan-5" target="_blank" rel="noopener">Peta bahan Sains T5 ↗</a><p>38°C, pH 7.0, BOD &lt;15 mg/L dan loji 2 MW ialah sasaran / andaian simulasi ini. Nilai optimum sebenar, piawaian pelepasan dan kos bergantung pada proses serta lokasi.</p></details>`;
$('screen-welcome').append(academyHub);
const academyJump=ngEl('a','academy-jump','↗ Masuk Akademi Sains · nota, kamus & eksperimen');academyJump.href='#academy-hub';document.querySelector('.hero-copy').append(academyJump);
const readLessons=new Set(storageGet('pome-academy-reading',[]));let selectedLesson=0;
function renderAcademyLesson(index){selectedLesson=index;const l=ACADEMY_LESSONS[index],article=$('academy-lesson');article.replaceChildren();const kicker=ngEl('span','academy-eyebrow',l.tag+' · '+l.time);const title=ngEl('h3',null,l.icon+' '+l.title);article.append(kicker,title,ngEl('p','academy-hook',l.hook));l.body.forEach(p=>article.append(ngEl('p',null,p)));const memory=ngEl('div','academy-memory');memory.append(ngEl('b',null,'🧠 Kunci ingatan'),ngEl('p',null,l.memory));const myth=ngEl('div','academy-myth');myth.append(ngEl('b',null,'Semak salah faham'),ngEl('p',null,l.misconception));const recall=ngEl('details','academy-recall');recall.append(ngEl('summary',null,'Uji ingatan: '+l.prompt),ngEl('p',null,l.answer));const mark=ngEl('button','tool-button',readLessons.has(l.id)?'✓ Sudah dibaca':'Tandakan sudah dibaca');mark.type='button';mark.onclick=()=>{readLessons.add(l.id);storageSet('pome-academy-reading',[...readLessons]);renderAcademyLesson(selectedLesson);};article.append(memory,myth,recall,mark,ngEl('small','academy-read-note','Tanda dibaca membantu ulang kaji; ia bukan ukuran penguasaan.'));document.querySelectorAll('#academy-tabs button').forEach((b,i)=>b.setAttribute('aria-pressed',i===index));$('academy-reading').textContent=readLessons.size+' / 8 nota ditandai dibaca';}
ACADEMY_LESSONS.forEach((l,i)=>{const b=ngEl('button',null,l.icon+' '+l.title);b.type='button';b.onclick=()=>renderAcademyLesson(i);$('academy-tabs').append(b);});renderAcademyLesson(0);
const academyTerms=[['POME','Air sisa daripada pemprosesan minyak sawit; mengandungi bahan organik.'],['BOD','Keperluan oksigen biokimia: oksigen yang digunakan dalam penguraian biologi pada keadaan ujian tertentu.'],['DO','Oksigen terlarut yang tersedia dalam air untuk hidupan akuatik.'],['Anaerob','Keadaan tanpa oksigen bebas. Sesetengah mikroorganisma boleh berfungsi dalam keadaan ini.'],['Aerob','Proses yang memerlukan oksigen. Pengudaraan membekalkan oksigen untuk pengurai.'],['Biogas','Campuran gas hasil penguraian anaerob, termasuk metana (CH₄) dan karbon dioksida.'],['RO','Osmosis songsang: tekanan menolak air melalui membran; bahan tertahan menjadi aliran pekatan.'],['pH','Ukuran keasidan atau kealkalian; pH 7 neutral pada kira-kira 25°C.'],['Kuasa / tenaga','MW ialah kadar penukaran tenaga; MWh ialah tenaga. Tenaga = kuasa × masa.'],['Jejak karbon','Pelepasan gas rumah hijau yang berkaitan dengan aktiviti atau produk.'],['CAPEX / ROI','CAPEX ialah kos modal awal. ROI mudah membandingkan aliran bersih tahunan dengan modal.'],['Eutrofikasi','Pertambahan nutrien boleh mencetuskan ledakan alga; pereputannya boleh mengurangkan DO.']];
function renderGlossary(){const query=$('academy-search').value.toLocaleLowerCase('ms');const dl=$('academy-glossary');dl.replaceChildren();academyTerms.filter(pair=>pair.join(' ').toLocaleLowerCase('ms').includes(query)).forEach(([k,v])=>dl.append(ngEl('dt',null,k),ngEl('dd',null,v)));if(!dl.children.length)dl.append(ngEl('p',null,'Tiada istilah sepadan. Cuba perkataan lain.'));}$('academy-search').oninput=renderGlossary;renderGlossary();
function updateAcademyLoad(){const n=Number($('academy-load').value);$('academy-load-label').textContent=n+'%';$('academy-bod').style.width=(10+n*.9)+'%';$('academy-do').style.width=(95-n*.8)+'%';$('academy-effect').textContent=n>65?'Banyak bahan organik → pengurai menggunakan lebih oksigen → risiko DO rendah meningkat.':n<30?'Kurang beban organik → kurang permintaan penguraian → oksigen lebih mudah dikekalkan.':'Beban meningkat. Bandingkan permintaan penguraian dengan bekalan oksigen dalam air.';}$('academy-load').oninput=updateAcademyLoad;updateAcademyLoad();

// Camera spells use a deliberate charge → aim → release sequence.
const MAGIC={mode:'classic',since:0,charge:0,readyUntil:0,cooldown:0,target:null,targetSince:0,lastSeen:0,x:0,y:0,session:0};window.POME_MAGIC=MAGIC;
const magicCopy={classic:'Gesture asal: jari untuk Peringkat 1, arah wajah untuk Peringkat 2. Kursor AI juga tersedia.',orb:'✋ Buka tapak tangan 0.7s untuk cas → gerakkan tangan ke kad bercahaya → 🤏 cubit untuk melontar. 5 jari / swipe untuk seterusnya.',fire:'✊ Genggam 0.6s untuk cas → gerakkan genggaman ke kad bercahaya → ✋ buka tapak tangan untuk tembak. 5 jari / swipe untuk seterusnya.'};
function createMagicPanel(compact){const p=ngEl('section',compact?'magic-panel magic-modebar':'magic-panel');if(!compact)p.append(ngEl('h3',null,'Pilih kuasa kamera anda'));const row=ngEl('div','magic-choices');for(const [key,label] of [['classic','✋ Klasik'],['orb','🔮 Magic Orb'],['fire','🔥 Fireball']]){const b=ngEl('button',null,label);b.type='button';b.dataset.magic=key;b.setAttribute('aria-pressed',key==='classic');b.onclick=()=>setMagicMode(key,true);row.append(b);}const copy=ngEl('p','magic-instructions',magicCopy.classic);copy.setAttribute('aria-live','polite');p.append(row,copy);return p;}
$('btn-start-game').before(createMagicPanel(false));$('options-grid').before(createMagicPanel(true));
const magicOrb=ngEl('div');magicOrb.id='magic-orb';magicOrb.setAttribute('aria-hidden','true');document.body.append(magicOrb);
function clearMagic(){MAGIC.since=0;MAGIC.charge=0;MAGIC.readyUntil=0;MAGIC.target=null;MAGIC.targetSince=0;magicOrb.style.display='none';document.querySelectorAll('.magic-target').forEach(el=>el.classList.remove('magic-target','magic-target-fire'));}
function refreshMagicInstructions(){if(magicActive()){const hint=$('question-stage-hint');if(hint)hint.textContent=MAGIC.mode==='orb'?'🔮 Tapak tangan untuk cas → halakan kad → cubit untuk lontar.':'🔥 Genggam untuk cas → halakan kad → buka tapak tangan untuk tembak.';document.querySelectorAll('#options-grid .option-card>div:first-child>span:last-child').forEach(el=>el.textContent=MAGIC.mode==='orb'?'🔮 Cas → Cubit':'🔥 Cas → Lepaskan');}}
function setMagicMode(mode,fromUser=false){MAGIC.mode=mode;MAGIC.session++;clearMagic();if(mode!=='classic')setCursorEnabledUI(false);document.querySelectorAll('[data-magic]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.magic===mode));document.querySelectorAll('.magic-instructions').forEach(p=>p.textContent=magicCopy[mode]);if(fromUser&&mode!=='classic'&&state.currentScreen==='game'&&state.stage<3){state.controlMode='vision';updatePremiumUI();startCameraAndAI();}if(mode!=='classic'&&state.currentScreen==='welcome'){const r=document.querySelector('[name=play-mode][value=vision]');r.checked=true;}if(state.currentScreen==='game'&&state.stage<3)renderCurrentQuestion();}
function magicActive(){return MAGIC.mode!=='classic'&&state.currentScreen==='game'&&state.stage<3&&!state.debugModeActive&&state.controlMode==='vision'&&!document.querySelector('div[id^="modal-"]:not(.hidden)')&&!scoreView.classList.contains('open');}
function launchMagic(target,now){if(!target||target.disabled||now<MAGIC.cooldown)return false;const index=Number(target.dataset.optIndex);if(!Number.isInteger(index))return false;const session=MAGIC.session,key=`${state.stage}-${state.questionIndex}`,mode=MAGIC.mode;MAGIC.cooldown=now+1000;const p=ngEl('div','magic-projectile'+(mode==='fire'?' fire':''));p.style.left=MAGIC.x+'px';p.style.top=MAGIC.y+'px';document.body.append(p);const box=target.getBoundingClientRect();requestAnimationFrame(()=>{p.style.left=box.x+box.width/2+'px';p.style.top=box.y+box.height/2+'px';p.style.transform='translate(-50%,-50%) scale(.35)';});clearMagic();setTimeout(()=>{p.remove();if(session!==MAGIC.session||state.currentScreen!=='game'||state.questionLocked||`${state.stage}-${state.questionIndex}`!==key||!magicActive())return;target.classList.add('magic-impact');submitQuizAnswer(index);setTimeout(()=>target.classList.remove('magic-impact'),550);},330);return true;}
function handleMagic(lm,info,now){
 if(!magicActive()){clearMagic();return false;}MAGIC.lastSeen=now;
 if(state.questionLocked){clearMagic();handleSwipe(lm,info,now);handleGameHandGesture(info.count,now,info);return true;}
 if(now<MAGIC.cooldown)return true;
 const grid=$('options-grid').getBoundingClientRect();if(grid.height<20)return true;
 // Palm stays stable during pinch, unlike using the moving index fingertip.
 const palm={x:(lm[0].x+lm[5].x+lm[9].x+lm[17].x)/4,y:(lm[0].y+lm[5].y+lm[9].y+lm[17].y)/4};
 const x=grid.left+clamp((1-palm.x-.12)/.76,0,1)*grid.width,y=grid.top+clamp((palm.y-.18)/.64,0,1)*grid.height;
 MAGIC.x=MAGIC.x?MAGIC.x*.4+x*.6:x;MAGIC.y=MAGIC.y?MAGIC.y*.4+y*.6:y;
 const cards=[...document.querySelectorAll('#options-grid .option-card:not(:disabled)')];let target=null;for(const c of cards){const r=c.getBoundingClientRect();if(MAGIC.x>=r.left&&MAGIC.x<=r.right&&MAGIC.y>=r.top&&MAGIC.y<=r.bottom)target=c;}
 if(target!==MAGIC.target){MAGIC.target=target;MAGIC.targetSince=now;}
 cards.forEach(c=>{c.classList.toggle('magic-target',c===target);c.classList.toggle('magic-target-fire',c===target&&MAGIC.mode==='fire');});
 const charging=MAGIC.mode==='orb'?info.count>=4&&!info.pinch:info.count===0;
 if(charging){if(!MAGIC.since)MAGIC.since=now;MAGIC.charge=clamp((now-MAGIC.since)/(MAGIC.mode==='orb'?700:600),0,1);if(MAGIC.charge>=1)MAGIC.readyUntil=now+5000;}else{MAGIC.since=0;if(now>MAGIC.readyUntil)MAGIC.charge=0;}
 const ready=MAGIC.readyUntil>now;magicOrb.style.display='block';magicOrb.classList.toggle('fire',MAGIC.mode==='fire');magicOrb.style.left=MAGIC.x+'px';magicOrb.style.top=MAGIC.y+'px';magicOrb.style.opacity=String(.35+MAGIC.charge*.65);magicOrb.style.setProperty('--magic-charge',ready?1:MAGIC.charge);magicOrb.style.setProperty('--magic-angle',(now/8)%360+'deg');
 const release=MAGIC.mode==='orb'?info.pinch:info.count>=4;
 updateGestureHUD(ready?(target?'Sasaran dikunci · '+(MAGIC.mode==='orb'?'CUBIT!':'BUKA TAPAK TANGAN!'):'Kuasa sedia · halakan ke kad'):MAGIC.mode==='orb'?'Buka tapak tangan untuk cas':'Genggam untuk cas',ready?100:MAGIC.charge*100);
 if(ready&&release&&target&&now-MAGIC.targetSince>=150)launchMagic(target,now);return true;
}
function magicMissing(now){if(now-MAGIC.lastSeen>250)clearMagic();}
$('btn-start-game').addEventListener('click',()=>{MAGIC.session++;clearMagic();MAGIC.cooldown=0;if(MAGIC.mode!=='classic'){state.controlMode='vision';document.querySelector('[name=play-mode][value=vision]').checked=true;}},true);
$('btn-ai-cursor').addEventListener('click',()=>{if(!NG.cursorEnabled&&MAGIC.mode!=='classic')setMagicMode('classic');},true);
const magicRender=renderCurrentQuestion;renderCurrentQuestion=function(){MAGIC.session++;clearMagic();magicRender();refreshMagicInstructions();};
const magicUpdateUI=updatePremiumUI;updatePremiumUI=function(){magicUpdateUI();refreshMagicInstructions();};
const magicShow=showScreen;showScreen=function(s){MAGIC.session++;clearMagic();return magicShow(s);};
const magicStop=stopCamera;stopCamera=function(){MAGIC.session++;clearMagic();return magicStop();};
document.addEventListener('visibilitychange',()=>{if(document.hidden){MAGIC.session++;clearMagic();}});

