function artFigure(key,interactive=true){const info=ART_INFO[key],fig=ngEl('figure','science-art');fig.dataset.art=key;const frame=ngEl('div','science-art-frame'),im=ngEl('img');im.src=POME_ART[key];im.alt=info.alt;im.width=1536;im.height=1024;im.loading='lazy';im.decoding='async';frame.append(im);const caption=ngEl('figcaption');caption.append(ngEl('b',null,info.title),ngEl('span',null,interactive?'Sentuh titik untuk meneroka · Ilustrasi konsep 3D':'Ilustrasi konteks · penerangan selepas menjawab'));fig.append(frame,caption);
 if(interactive){const description=ngEl('div','art-description');description.setAttribute('role','status');description.append(ngEl('b',null,'Teroka rajah'),ngEl('p',null,'Pilih satu titik bercahaya pada gambar.'));info.spots.forEach(([x,y,n,title,copy],i)=>{const btn=ngEl('button','art-hotspot',n);btn.type='button';btn.style.left=x+'%';btn.style.top=y+'%';btn.setAttribute('aria-label',title);btn.setAttribute('aria-pressed','false');btn.onclick=()=>{frame.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed','false'));btn.setAttribute('aria-pressed','true');description.replaceChildren(ngEl('b',null,title),ngEl('p',null,copy));};frame.append(btn);});fig.append(description);}return fig;}
