Object.entries(ART_INFO).forEach(([key,info],i)=>{const b=ngEl('button','tool-button',info.title);b.type='button';b.dataset.artTab=key;b.setAttribute('aria-pressed',i===0);b.onclick=()=>{visualLibrary.querySelectorAll('[data-art-tab]').forEach(el=>el.setAttribute('aria-pressed',el===b));$('visual-library-figure').replaceChildren(artFigure(key));};visualLibrary.querySelector('.art-library-tabs').append(b);});academyHub.before(visualLibrary);$('visual-library-figure').append(artFigure('plant'));
