function selectPlantStation(i){PLANT3D.selected=i;$('plant3d-station-title').textContent=(i+1)+'. '+plantStations[i][0];$('plant3d-station-copy').textContent=plantStations[i][1];$('plant3d-station-metric').textContent=plantStations[i][2];plantModal.querySelectorAll('[data-station]').forEach((b,k)=>b.setAttribute('aria-pressed',k===i));}
plantStations.forEach((s,i)=>{const b=ngEl('button',null,(i+1)+'. '+s[0]);b.type='button';b.dataset.station=i;b.onclick=()=>selectPlantStation(i);plantModal.querySelector('.plant3d-stations').append(b);});selectPlantStation(0);
