plantModal.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closePlant3D();}if(e.key==='Tab'){const list=[...plantModal.querySelectorAll('button,input,canvas')],a=list[0],b=list.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus();}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus();}}});
