$('plant3d-zoom').oninput=e=>setPlantZoom(Number(e.target.value)/100);$('plant3d-left').onclick=()=>PLANT3D.yaw-=.3;$('plant3d-right').onclick=()=>PLANT3D.yaw+=.3;
$('plant3d-explode').onclick=()=>{PLANT3D.explode=!PLANT3D.explode;$('plant3d-explode').setAttribute('aria-pressed',PLANT3D.explode);};$('plant3d-auto').onclick=()=>{PLANT3D.auto=!PLANT3D.auto;$('plant3d-auto').setAttribute('aria-pressed',PLANT3D.auto);};$('plant3d-reset').onclick=()=>{PLANT3D.yaw=-.35;PLANT3D.pitch=.52;PLANT3D.explode=false;PLANT3D.auto=false;$('plant3d-explode').setAttribute('aria-pressed','false');$('plant3d-auto').setAttribute('aria-pressed','false');setPlantZoom(1);};
plantCanvas.addEventListener('wheel',e=>{e.preventDefault();setPlantZoom(PLANT3D.zoom-e.deltaY*.001);},{passive:false});
let plantPointerStart=null,pinchStart=null;
plantCanvas.addEventListener('pointerdown',e=>{plantCanvas.setPointerCapture(e.pointerId);PLANT3D.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});plantPointerStart={x:e.clientX,y:e.clientY,moved:0};PLANT3D.auto=false;$('plant3d-auto').setAttribute('aria-pressed','false');if(PLANT3D.pointers.size===2){const [a,b]=[...PLANT3D.pointers.values()];pinchStart={d:Math.hypot(a.x-b.x,a.y-b.y),zoom:PLANT3D.zoom};}});
plantCanvas.addEventListener('pointermove',e=>{const old=PLANT3D.pointers.get(e.pointerId);if(!old)return;const dx=e.clientX-old.x,dy=e.clientY-old.y;PLANT3D.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(plantPointerStart)plantPointerStart.moved+=Math.abs(dx)+Math.abs(dy);if(PLANT3D.pointers.size===2&&pinchStart){const [a,b]=[...PLANT3D.pointers.values()];setPlantZoom(pinchStart.zoom*Math.hypot(a.x-b.x,a.y-b.y)/Math.max(1,pinchStart.d));}else{PLANT3D.yaw+=dx*.008;PLANT3D.pitch=clamp(PLANT3D.pitch+dy*.004,.18,1.02);}});
function releasePlantPointer(e){if(plantPointerStart?.moved<8&&PLANT3D.pointers.size===1){const r=plantCanvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;const hit=PLANT3D.hits.find(h=>Math.hypot(h.x-x,h.y-y)<25);if(hit)selectPlantStation(hit.i);}PLANT3D.pointers.delete(e.pointerId);pinchStart=null;plantPointerStart=null;}
