 // Pipes and moving flow beads are a conceptual overlay, not a hydraulic calculation.
 for(let i=0;i<3;i++){const a=projectPlant([xs[i]+1.05,.75,.2],w,h),b=projectPlant([xs[i+1]-1.05,.75,.2],w,h);plantCtx.strokeStyle=['#e3ae55','#b2de75','#75e1d6'][i];plantCtx.lineWidth=5;plantCtx.beginPath();plantCtx.moveTo(a.x,a.y);plantCtx.lineTo(b.x,b.y);plantCtx.stroke();const t=matchMedia('(prefers-reduced-motion: reduce)').matches?.5:(now/1800+i*.25)%1;plantCtx.fillStyle='#f4ffe0';plantCtx.beginPath();plantCtx.arc(a.x+(b.x-a.x)*t,a.y+(b.y-a.y)*t,3,0,Math.PI*2);plantCtx.fill();}
