function s3DropTarget(x,y){const direct=document.elementFromPoint(x,y)?.closest('.s3-zone-item:not(:disabled)');if(direct)return direct;let nearest=null,best=Infinity;const headerBottom=document.querySelector('header').getBoundingClientRect().bottom;for(const el of document.querySelectorAll('.s3-zone-item:not(:disabled)')){const r=el.getBoundingClientRect(),dx=Math.max(r.left-x,0,x-r.right),dy=Math.max(r.top-y,0,y-r.bottom),dist=Math.hypot(dx,dy);if(y<headerBottom+5||r.bottom<headerBottom||r.top>innerHeight)continue;if(dist<=26&&dist<best){nearest=el;best=dist;}}return nearest;}
