// The only boundary between the new modules and the existing global game engine.
window.POME_ECO_FOUNDATION=window.mountEcoFoundation({
 openPlant:i=>openPlant3D(i),
 openTool:mission=>{if(mission.id==='final'){POME_BLENDER_LAB.open(0);POME_BLENDER_LAB.setScenario('monsoon');return;}if(mission.id==='restore'){openRecovery();return;}if(mission.id==='operate'){openOperator();return;}if(mission.id==='build'){openTreatment();return;}if(mission.id==='river'){openRiver();return;}if(mission.id==='discover'){openDiscovery();return;}if(mission.tool==='plant'){openPlant3D(mission.station||0);return;}document.getElementById('eco-legacy-library').open=true;document.getElementById('academy-load').scrollIntoView({behavior:document.documentElement.dataset.reducedMotion==='true'?'instant':'smooth',block:'center'});document.getElementById('academy-load').focus({preventScroll:true});}
});
// Native dialogs must also suspend question gestures.
const ecoCanQuiz=canQuizGesture;canQuizGesture=()=>!document.querySelector('dialog[open]')&&ecoCanQuiz();

const hubReturn=document.createElement('button');hubReturn.type='button';hubReturn.id='eco-return-hub';hubReturn.className='eco-button eco-button-primary erh-return';hubReturn.textContent='↶ Return to Eco Lab';hubReturn.hidden=true;document.body.append(hubReturn);
function openResearchHub(){clearPointer();if(document.activeElement===hubReturn||!document.activeElement?.getClientRects().length)document.getElementById('eco-open-hub-header')?.focus();hubReturn.hidden=true;window.POME_RESEARCH_HUB.open();}
function revealResearchLibrary(){if(state.currentScreen==='game')document.getElementById('btn-save-exit').click();document.getElementById('eco-legacy-library').open=true;}
function focusResearchTarget(el){el.scrollIntoView({behavior:document.documentElement.dataset.reducedMotion==='true'?'instant':'smooth',block:'center'});if(!el.hasAttribute('tabindex')&&!el.matches('button,input'))el.tabIndex=-1;el.focus({preventScroll:true});}
window.POME_RESEARCH_HUB.setNavigation(tool=>{document.getElementById('eco-open-hub-header').focus({preventScroll:true});document.body.append(hubReturn);hubReturn.hidden=false;
 if(tool==='plant'||tool==='control'){openPlant3D(tool==='plant'?0:2);document.querySelector('.pbl-top').append(hubReturn);return;}
 if(tool==='oxygen'){hubReturn.hidden=true;openRiver();return;}
 if(tool==='sample'){hubReturn.hidden=true;openMicro('hub');return;}
 if(tool==='missions'){if(state.currentScreen==='game')document.getElementById('btn-save-exit').click();focusResearchTarget(document.getElementById('eco-mission-map'));return;}
 revealResearchLibrary();if(tool==='sample'){document.getElementById('learning-notes').open=true;window.setMicroscopeSample('raw');focusResearchTarget(document.getElementById('micro-btn-raw'));}else focusResearchTarget(document.getElementById('academy-load'));
});
hubReturn.onclick=()=>{if(POME_BLENDER_LAB.lab.open)POME_BLENDER_LAB.close();if(PLANT3D.open)closePlant3D();openResearchHub();};
const hubLaunch=document.createElement('button');hubLaunch.type='button';hubLaunch.id='eco-enter-hub';hubLaunch.className='eco-button eco-button-primary';hubLaunch.textContent='Enter the 3D Eco Lab ↗';hubLaunch.onclick=openResearchHub;document.querySelector('.eco-hero-actions').prepend(hubLaunch);document.getElementById('eco-enter-lab').classList.replace('eco-button-primary','eco-button-quiet');
const hubHeader=hubLaunch.cloneNode(true);hubHeader.id='eco-open-hub-header';hubHeader.className='tool-button pbl-launch';hubHeader.textContent='✦ Eco Lab 3D';hubHeader.onclick=openResearchHub;document.getElementById('btn-open-blender-lab').before(hubHeader);
const hubCaption=document.createElement('p');hubCaption.className='eco-hub-callout';hubCaption.textContent='Five research stations. Explore the room, choose an object and follow your question.';document.querySelector('.eco-hero-actions').before(hubCaption);
const hubCursor=runCursor;runCursor=function(lm,info,now){if(POME_RESEARCH_HUB.state.open){s3Run(lm,info,now);return;}hubCursor(lm,info,now);};
function openDiscovery(){clearPointer();if(POME_RESEARCH_HUB.state.open)POME_RESEARCH_HUB.close();if(POME_BLENDER_LAB.lab.open)POME_BLENDER_LAB.close();hubReturn.hidden=true;POME_DISCOVERY.open();}
