// Optional camera input for the new learning missions. Legacy quiz controls remain separate.
(()=>{
 const roots=[...document.querySelectorAll('#modal-blender-lab,#modal-eco-research-hub,#modal-pome-discovery,#modal-pome-river,#modal-pome-build,#modal-pome-operate,#modal-pome-micro,#modal-pome-restore')];
 let prefs={mode:'dwell',dwell:1400};try{const p=JSON.parse(localStorage.getItem('pome-eco-gesture-v1'));if(['dwell','pinch'].includes(p?.mode))prefs.mode=p.mode;if([1400,2000].includes(p?.dwell))prefs.dwell=p.dwell;}catch{}
 let paused=false,busy=false,root=null,last=0,neutral=0,armed=false,target=null,since=0,latched=null,gripped=false,releaseAt=0,range=null,edge=0,edgeSince=0,anchor=null;
 const bars=[],options=new Map();let handDrag=null,sceneTarget=false;const physical=()=>window.POME_BLENDER_LAB?.physical?.();
 const active=()=>document.querySelector('dialog[open]')?null:roots.find(e=>!e.classList.contains('hidden')&&e.getClientRects().length);
 function reset(){handDrag?.handCancel();handDrag=null;sceneTarget=false;target?.classList.remove('ai-target');target=null;since=0;latched=null;armed=false;neutral=0;gripped=false;releaseAt=0;range=null;edge=0;edgeSince=0;last=0;anchor=null;cursor.style.setProperty('--cursor-pct','0%');}
 function save(){try{localStorage.setItem('pome-eco-gesture-v1',JSON.stringify({version:1,...prefs}));}catch{}sync();reset();}
 function sync(message){for(const bar of bars){bar.querySelector('[data-eg-camera]').textContent=busy?'Starting camera…':NG.cursorEnabled?'Stop camera controls':'Start camera controls';bar.querySelector('[data-eg-camera]').disabled=busy;bar.querySelector('[data-eg-pause]').disabled=!NG.cursorEnabled;bar.querySelector('[data-eg-pause]').textContent=paused?'Resume hand input':'Pause hand input';bar.querySelector('[data-eg-pause]').setAttribute('aria-pressed',paused);bar.querySelectorAll('[data-eg-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.egMode===prefs.mode));bar.querySelectorAll('[data-eg-speed]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.egSpeed===prefs.dwell));if(message)bar.querySelector('[data-eg-status]').textContent=message;}}
 async function camera(){if(busy)return;const stopping=NG.cursorEnabled;busy=true;sync();try{await toggleAICursor();if(!NG.cursorEnabled){state.controlMode="manual";stopCamera();updatePremiumUI();}else if(active()){await syncActiveVideo();mini.hidden=false;}}finally{busy=false;paused=false;reset();sync(NG.cursorEnabled?'Show an open hand briefly, then point with your index finger.':stopping?'Camera controls are off. Mouse, touch and keyboard still work.':'Camera could not start. Check browser camera permission and try again. Mouse and touch still work.');}}
 for(const r of roots){const bar=document.createElement('section');bar.className='eco-gesture-bar';bar.innerHTML=`<div><button type="button" data-eg-camera>Start camera controls</button><button type="button" data-eg-pause disabled>Pause hand input</button><details><summary>Hand-control guide & preferences</summary><p>Optional: start the camera only when you want to use it. Show an open hand briefly to arm input. Point with your index finger. Keep the cursor still to select, or pinch thumb and index finger. Open your fingers before the next pinch.</p><div><button type="button" data-eg-mode="dwell">Hold to select + pinch</button><button type="button" data-eg-mode="pinch">Pinch only</button></div><div><button type="button" data-eg-speed="1400">Hold 1.4 seconds</button><button type="button" data-eg-speed="2000">Hold 2 seconds</button></div><p>Pinch and move across a slider to adjust it; release to finish. Point at an empty top/bottom edge to scroll. Answer lists open as large buttons. Build the treatment system using module, foundation and pipe buttons. Touch or mouse can always take over.</p><p>Move away from a button before selecting it again. In Makmal 3D, point at equipment and pinch or hold to select. Pinch the green inlet valve and move right/up to open it; left/down closes it. Open fingers to release. Use Overview to return from a close-up. Tracking loss cancels a held slider or valve. Pause suspends hand input; use touch/mouse to resume. Camera permission is requested by your browser; these preferences never start the camera automatically.</p></details></div><small data-eg-status role="status">Camera is optional. No camera starts automatically.</small>`;r.querySelector('.pbl-dialog,.rv-shell,.pd-shell,.erh-shell')?.prepend(bar);if(!bar.isConnected)r.prepend(bar);bars.push(bar);
  bar.querySelector('[data-eg-camera]').onclick=camera;bar.querySelector('[data-eg-pause]').onclick=()=>{paused=!paused;reset();sync(paused?'Hand input paused. Use touch or mouse to resume.':'Show an open hand to resume.');};bar.querySelectorAll('[data-eg-mode]').forEach(b=>b.onclick=()=>{prefs.mode=b.dataset.egMode;save();});bar.querySelectorAll('[data-eg-speed]').forEach(b=>b.onclick=()=>{prefs.dwell=+b.dataset.egSpeed;save();});
 }
 function menu(select){let box=options.get(select);if(!box){box=document.createElement('div');box.className='eco-gesture-options';select.after(box);options.set(select,box);}for(const [s,b] of options)if(s!==select)b.hidden=true;box.replaceChildren();box.hidden=false;for(const opt of select.options){if(!opt.value||opt.disabled)continue;const b=document.createElement('button');b.type='button';b.textContent=opt.textContent;b.onclick=()=>{if(select.disabled)return;select.value=opt.value;select.dispatchEvent(new Event('input',{bubbles:true}));select.dispatchEvent(new Event('change',{bubbles:true}));box.hidden=true;};box.append(b);}const cancel=document.createElement('button');cancel.type='button';cancel.textContent='Cancel choices';cancel.onclick=()=>box.hidden=true;box.append(cancel);}
 function hit(x,y){const e=document.elementFromPoint(x,y);sceneTarget=false;if(e?.id==='pbl-canvas'){const button=physical()?.handTarget(x,y);if(button){sceneTarget=true;return button;}}let t=e?.closest('button,input[type=range],input[type=checkbox],select,summary,[role=tab],a[href]');if(!t){const label=e?.closest('label');t=label?.control||null;}return t&&root?.contains(t)&&!t.disabled&&t.getClientRects().length?t:null;}
 function action(t,now){if(!t||t.disabled)return;latched=t;anchor={x:NG.pointer.x,y:NG.pointer.y};since=now;cursor.style.setProperty('--cursor-pct','0%');if(t.matches('select'))menu(t);else if(t.matches('input[type=range]')){adjustRange(t,NG.pointer.x);t.dispatchEvent(new Event('change',{bubbles:true}));}else t.click();}
 const oldVideo=activeVisionVideo;activeVisionVideo=function(){return active()&&!state.debugModeActive?$('ai-mini-video'):oldVideo();};const oldZoom=twoHandZoom;twoHandZoom=function(...args){return active()?false:oldZoom(...args);};
 const oldClear=clearPointer;clearPointer=function(){reset();oldClear();if(active()&&NG.cursorEnabled)sync('Tracking paused. Show an open hand to resume.');};
 const oldRun=runCursor;runCursor=function(lm,info,now){const nextRoot=active();if(!nextRoot){if(root){reset();root=null;}oldRun(lm,info,now);return;}if(!NG.cursorEnabled||document.hidden||paused){reset();cursor.style.display='none';return;}
  if(root!==nextRoot||last&&now-last>250){reset();root=nextRoot;}const dt=last?Math.min(.1,(now-last)/1000):0;last=now;NG.pointer.lastSeen=now;
  const x=clamp((1-lm[8].x-.1)/.8,0,1)*innerWidth,y=clamp((lm[8].y-.08)/.84,0,1)*innerHeight,p=NG.pointer;p.x=p.x==null?x:p.x+(x-p.x)*.4;p.y=p.y==null?y:p.y+(y-p.y)*.4;cursor.style.display='block';cursor.style.left=p.x+'px';cursor.style.top=p.y+'px';cursor.classList.remove('gun');
  let ratio=info.pinchRatio;if(lm[0]&&lm[9]&&lm[5]&&lm[17]&&lm[4])ratio=pointDistance(lm[4],lm[8])/Math.max(.035,pointDistance(lm[0],lm[9]),pointDistance(lm[5],lm[17])*.85);
  const held=Number.isFinite(ratio)?ratio<(gripped?.62:.43):!!info.pinch;
  if(!armed){if(!held&&info.count>=4){if(!neutral)neutral=now;if(now-neutral>=300){armed=true;sync('Hand input ready. Point, hold or pinch to select.');}}else neutral=0;return;}
  if(handDrag){if(held){releaseAt=0;handDrag.handMove(p.x,p.y);}else if(!releaseAt)releaseAt=now;else if(now-releaseAt>=120){handDrag.handCancel();handDrag=null;gripped=false;releaseAt=0;anchor={x:p.x,y:p.y};}return;}
  if(range){if(!range.isConnected||range.disabled||!root.contains(range)){range=null;gripped=held;return;}if(held){releaseAt=0;adjustRange(range,p.x);}else if(!releaseAt)releaseAt=now;else if(now-releaseAt>=120){range.dispatchEvent(new Event('change',{bubbles:true}));range=null;gripped=false;releaseAt=0;}return;}
  if(anchor){if(Math.hypot(p.x-anchor.x,p.y-anchor.y)<=28){gripped=held;return;}anchor=null;since=now;}const t=hit(p.x,p.y),direction=!t?(p.y>innerHeight-55?1:p.y<55&&root.scrollTop>0?-1:0):0;
  if(direction){if(edge!==direction){edge=direction;edgeSince=now;}if(now-edgeSince>500)root.scrollTop+=direction*dt*420;target?.classList.remove('ai-target');target=null;latched=null;since=now;gripped=held;cursor.style.setProperty('--cursor-pct','0%');return;}edge=0;
  if(t!==target){target?.classList.remove('ai-target');target=t;since=now;latched=null;releaseAt=0;}t?.classList.add('ai-target');
  if(held&&!gripped&&t&&now-since>=150){if(sceneTarget&&t.dataset.pi==='Valve_Main_Inlet'){handDrag=physical();handDrag.handStart(p.x,p.y);latched=t;}else{action(t,now);if(t.matches('input[type=range]'))range=t;}}
  else if(!held&&prefs.mode==='dwell'&&t&&latched!==t){const pct=Math.min(1,(now-since)/prefs.dwell);cursor.style.setProperty('--cursor-pct',pct*100+'%');if(pct===1)action(t,now);}else cursor.style.setProperty('--cursor-pct','0%');
  gripped=held;
 };
 // Reflect existing global ON/OFF controls and cancel any pending selection when a mission closes.
 const observer=new MutationObserver(()=>{const next=active();document.documentElement.dataset.ecoHandScene=String(!!next);if(next!==root){reset();root=next;}for(const [s,b] of options)if(s.disabled||!s.closest('[role=dialog]')?.getClientRects().length)b.hidden=true;sync();});for(const r of roots)observer.observe(r,{attributes:true,attributeFilter:['class']});observer.observe(cursorButton,{attributes:true,attributeFilter:['aria-pressed']});
 document.addEventListener('visibilitychange',()=>{reset();cursor.style.display='none';});sync();
 window.POME_ECO_GESTURES={preferences:()=>({...prefs}),status:()=>({armed,paused,range:range?.id||null,handDrag:!!handDrag,target:target?.id||null}),reset};
})();

window.POME_MOUNT_EXPERIENCE?.();
// One visible investigation owns input/render work. Assets remain cached for bounded reuse.
const sceneApis=['POME_BLENDER_LAB','POME_RESEARCH_HUB','POME_DISCOVERY','POME_RIVER','POME_TREATMENT','POME_OPERATOR','POME_MICRO','POME_RECOVERY'];
for(const key of sceneApis){const api=window[key];if(!api?.open)continue;const enter=api.open.bind(api);api.open=(...args)=>{for(const other of sceneApis){if(other===key)continue;const a=window[other];if(a&&(a.state?.open||a.lab?.open))a.close();}document.documentElement.dataset.sceneActive="true";return enter(...args);};}

window.POME_MOUNT_LOCALIZER?.();

const sceneVisibility=new MutationObserver(()=>{document.documentElement.dataset.sceneActive=String(sceneApis.some(k=>window[k]?.state?.open||window[k]?.lab?.open));});for(const el of document.querySelectorAll('[role="dialog"]'))sceneVisibility.observe(el,{attributes:true,attributeFilter:["class"]});

